const D: MvBook[] = [{"u":"Молитва священника на сповіді","e":"Prayer of the Priest at Confession","secs":[{"ps":["Бо́же, Спаси́телю наш, І́же проро́ком Твої́м Нафа́ном пока́явшемуся Дави́ду о свої́х согріше́ніїх оставле́ніє дарова́вий, і Манассі́їну в покая́ніє моли́тву приє́мий, Сам і раба́ Твоєго́ (і́м'я), ка́ющагося о ни́хже соді́ла согріше́ніїх, прийми́ оби́чним Твої́м человіколю́бієм, презира́яй єму́ вся соді́янная, оставля́яй непра́вди і превосходя́й беззако́нія.","Ти бо рекл єси́, Го́споди: хоті́нієм не хощу́ сме́рти грі́шника, но я́ко є́же обрати́тися і жи́ву би́ти єму́, і я́ко се́дьмдесят седьмери́цею оставля́ти гріхи́. Поне́же я́ко вели́чество Твоє́ безприкла́дноє і ми́лость Твоя́ безмі́рная. А́ще бо беззако́нія на́зриши, кто постої́ть?","Я́ко Ти єси́ Бог ка́ющихся і Тебі́ сла́ву возсила́єм, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Се, ча́до, Христо́с неви́димо стої́ть, приє́мля іспові́даніє твоє́, не усрами́ся, ніже́ убо́йся, і да не скри́єши что от мене́, но не обину́яся рци вся, єли́ка соді́лал єси́, да приї́меши оставле́ніє от Го́спода на́шего Ісу́са Христа́. Се і іко́на Єго́ пред на́ми, аз же то́чію свиді́тель єсьм, да свиді́тельствую пред Ним вся, єли́ка рече́ши мні: а́ще ли что скри́єши от мене́, сугу́б гріх і́маши. Внемли́ у́бо: поне́же бо прише́л єси́ во враче́бницю, да не неісці́лен отидеши.","«Госпо́дь і Бог наш, Ісу́с Христо́с, благода́тію і щедро́тами Своєго́ человіколю́бія да прости́ть ті ча́до (і́м'я) вся согріше́нія твоя́. І аз, недосто́йний ієре́й, вла́стію Єго́ мні да́нною, проща́ю і разріша́ю тя от всіх гріхо́в твої́х, во І́м'я Отця́ і Си́на, і Свята́го Ду́ха. Амі́нь»."]}],"notes":[]},{"u":"Кондак блаженному Прокопію, Христа ради юродивому, Устюзькому","e":"Kontakion to the Blessed Procopius of Ustyug, Fool for Christ","secs":[{"ps":["Христа́ ра́ди юро́дством возду́шная мита́рства на рука́х а́нгельських неприкоснове́нно преше́д, ца́рськаго дости́гл єси́ престо́ла і от Царя́ всіх Христа́ Бо́га дар приє́м благода́ть ісціле́ній, мно́гими бо чудеси́ твої́ми і зна́менієм стра́шним удиви́л єси́ град твой Вели́кий У́стюг: лю́дем твої́м ми́лость іспроси́в, ми́ро от честна́го о́браза Пресвяти́я Богоро́диці моли́твою ізве́л єси́ і неду́жним по́дал єси́ цільби́. Тім же мо́лим тя, чудоно́сче Проко́піє: моли́ Христа́ Бо́га непреста́нно пода́ти гріхо́в на́ших проще́ніє."]}],"notes":[]},{"u":"Молитва про дім, на який нападають злі духи","e":"Prayer for a House Troubled by Evil Spirits","secs":[{"ps":["Го́споди Бо́же спасе́нія на́шего, Си́не Бо́га жива́го, на херуви́міх носи́мий, преви́ше сий вся́каго нача́ла і вла́сті, і си́ли, і госпо́дства: Ти єси́ ве́лій і стра́шний над всі́ми су́щими окре́ст Тебі́: Ти єси́ сотвори́вий зе́млю в крі́пості Твоє́й, і іспра́вивий вселе́нную в прему́дрости Твоє́й: тряси́й поднебе́сную от основа́ній, столпи́ же єя́ неподви́жни: глаго́ляй со́лнцю, і не возсія́єть, зві́зди же запечатлі́яй: запреща́яй мо́рю, і ізсуша́яй є: єго́же я́рость та́єть нача́ла і вла́сті, і ка́меніє сотро́шася от Тебе́. Врата́ мі́дная стерл єси́, і вереї́ желі́зния сломи́л єси́: крі́пкаго связа́л єси́, і сосу́ди єго́ раздра́л єси́: мучи́теля кресто́м Твої́м низложи́л єси́, і змі́я у́дицею вочелові́ченія Твоєго́ привле́кл єси́, і у́зами мра́ка в та́ртарі посади́в связа́л єси́.","Сам у́бо Го́споди, отжени́ і в бі́гство претвори́ вся́коє дия́вольськоє ді́йство, і вся́коє сатани́нськоє нахожде́ніє, вся́кий наві́т сопроти́вния і належа́щия си́ли от кро́ва сего́, і от одержи́мих от него́, і от обходя́щих под ним; вся су́щия во дому́ сем сохрани́, ізбавля́я їх от стра́ха нощна́го, і стріли́ летя́щия во дні, от ве́щі во тьмі преходя́щия, от сря́ща і де́мона полу́деннаго. Я́ко Ти єси́ Бо́же утвержде́ніє моє́, крі́пкий облада́тель, князь ми́ра, Оте́ць бу́дущаго ві́ка, і ца́рство Твоє́ ца́рство ві́чноє: і Тебі́ єди́наго єсть ца́рство, і си́ла, і сла́ва, со Отце́м і Святи́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського при життєвих невдачах","e":"Prayer of St John of Kronstadt in Life’s Setbacks","secs":[{"ps":["Сла́ва Тебі́, Го́споди, О́тче наш, прему́дрий Іспита́телю любві́ моєя́ к Тебі́ і к бли́жнему моєму́. Не оставля́й м'я без іскуше́ній, – а́ще прему́дрості і пра́вді Твоє́й уго́дно і благопотре́бно бу́деть, – ні єди́ного дня живота́ моєго́; да насади́ться, да утверди́ться, да очи́ститься і возви́ситься любо́в моя́ к Тебі́ і к бли́жнему моєму́, і да не явлю́ся на суді́ Твоє́м тощ пред Лице́м Твої́м."]}],"notes":[]},{"u":"Молитва до Бога про збереження дому від пожежі","e":"Prayer to God to Preserve a House from Fire","secs":[{"ps":["Тя, Бо́га, Отця́ Всемогу́щего, усе́рдно мо́лим о до́мі сем, живу́щих в нем і о всем іму́ществе, в нем находя́щемся: благослови́, освяти́ си́лою Свято́го Креста́, сохрани́ от о́гненного пла́мені, от уда́ра мо́лнії ізба́в і да́руй вся́кіє бла́га. Благослови́, Влади́ко, і освяти́ дом сей, как благослови́л Ти дом Авраа́ма, Ісаа́ка, і Іа́кова, і да обита́ють в нем А́нгели благослове́нія Твоєго́; живу́щих же в нем от разжже́нія огня́, мо́лнії і злоумишле́нія дия́вольського сохрани́ і спаси́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Кондак священномученику Харалампію (при голоді)","e":"Kontakion to the Hieromartyr Charalampus (in Famine)","secs":[{"ps":["Я́ко му́ченик і іспові́дник цвіт, / двойни́м вінце́м Христо́с тя увінча́, / возвели́чив безчи́сленними чудеси́ на землі́, / но я́ко благода́ть Госпо́дню явля́я нам, / ві́рно к тебі́ прибега́ющим, / да́руй мир, помози́ в напа́стіх і лю́тих біда́х, // святі́йший Харала́мпіє."]}],"notes":[]},{"u":"Молитви ув’язненого","e":"Prayers of a Prisoner","secs":[{"ps":["Долготерпіли́ве і Многоми́лостиве Го́споди! Припа́даю к Тебі́, аз сий у́зник, моля́ся те́плі: я́коже си́льний Сампсо́н позна́ своє́ безси́ліє, єгда́ бі под стра́жею, і обрати́ся к Тебі́, всеси́льному Бо́гу, окова́нний пу́ти желі́зними; я́коже нечести́вий Манассі́я в пліне́нії і темни́ці взиська́ Тебе́, і́стиннаго Бо́га; я́коже пліне́ннії іуде́ї па́че на землі́ чужде́й уразумі́ша Тебе́, Бо́га оте́ць свої́х; я́коже блу́дний син воспом'яну́ отця́ своєго́, єгда́, отше́д на страну́ дале́че, нача́ ізгиба́ти гла́дом: та́ко і аз отни́ні то́кмо познаю́ Тебі́ і прилі́жніє молю́. Отчужде́н єсьм аз ни́ні обще́нія с челові́ки: но Ти єси́ взиску́яй отчужде́нних. Ність со мно́ю зді ні оте́ць, ні мать, ні брат, ні єди́н от друго́в мої́х, да помо́гуть мі; не усли́шить отсю́да моєго́ во́пля нікто́же от них: но Ти близ єси́ всім скорб'я́щим і призива́ющим Тя во і́стині. О милосе́рдний Бо́же! А́ще аз і па́че числа́ песка́ морська́го согріши́х і не смі́ю воззрі́ти на висоту́ небе́сную от мно́жества гріхо́в мої́х: но Ти, непам'ятозло́бив сий, прийми́ м'я ка́ющагося. Тебі́ єди́ному согріши́х, но і Тебі́ єди́ному ка́юся, Всеми́лостиве Го́споди! Пре́жде да́же до конця́ не поги́бну, спаси́ м'я."],"h":"Молитва 1, до Господа"},{"ps":["Го́споди Бо́же мой! По єди́ній то́кмо благода́ті Своє́й Ти от небитія́ м'я в битіє́ приве́л єси́, і Свої́м о́бразом украси́ єси́ м'я. Аз не поми́слих дово́льні благодари́ти Тя, ні я́ко дарова́л єси́ мні жизнь, ніже́ я́ко поста́вил єси́ м'я над всі́ми земни́ми тва́рми, а́ки царя́ їх. Ти сподо́бил м'я єси́ прия́ти свято́є Креще́ніє, єгда́ біх младе́нець. Аз же із ді́тства моєго́ не сохрани́х благода́ті креще́нія: наче́н бо ізмла́да лга́ти, скверносло́вити, составля́ти сладостра́стния пі́сні, ліни́тися, утаїва́ти чужо́є, проти́виться повелі́нієм мої́х роди́телей, презира́ти до́бриє сові́ти старі́йших м'я, мла́дших же мене́ лі́ти всу́є би́ти руко́ю. Єгда́ же прийдо́х во во́зраст му́жества, преда́хся разли́чним страсте́м, пія́нству, блуду́, злоприобре́тенію, гні́ву, го́рдості. І ті́ло моє́ і ду́шу всеконе́чно оскверни́х гріхми́. В ку́ю скве́рну тіле́сную не впадо́х аз окая́нний? В ко́єй нечистоті́ пло́тстій не вообрази́х себі́ я́вственні і в сновиді́нії? Ко́є зло не поми́слих в душі́ моє́й? Коль мно́гая неподо́бная мечта́нія взидо́ша в ду́шу мою́! Коли́ко себ'ялю́бець бих аз, не помишля́яй імі́ти христия́нськия любве́ к бли́жнему! Ожесточи́х аз, окая́нний, моє́ се́рдце толи́ко, я́ко ні от моле́ній, ні от слез, ніже́ от сто́на стра́ждущих по моє́й зло́бі іли́ кори́сти, не умиля́хся. По сем же моя́ преступле́нія не іспові́дах пред судія́ми. Мно́жицею лгах на суді́ і не смуща́хся. Не бисть пред очи́ма мої́ма ні стиді́нія челові́чеська, ні стра́ха Бо́жия. Забива́х зау́тра і во ве́чер твори́ти моли́тви, ніже́ єди́ною огради́ти себі́ кре́стним зна́менієм, явля́яй себе́ я́ко безбо́жна. Уклоня́хся і в бесі́ді с бли́жніми мої́ма воспомина́ти і́м'я моєго́ Созда́теля і Спаси́теля. І́м'я же врага́ спасе́нія моєго́, дия́вола, — уви́ мні, неразу́мному! — поча́сту воспомина́х. А́ще і прия́х блага́я от руки́ Твоєя́, ми́лостиве Го́споди, а́ще і ви́діх болі́зні і іни́я посіще́нія на мої́х бли́жніх: оба́че от сего́ не умудря́хся к покая́нію пред Тобо́ю. І та́ко до конця́ аз отступи́х от Тебе́, Го́спода моєго́! Отидо́х от Тебе́, я́ко блу́дний син, на страну́ дале́че: удали́хся не мі́стом, — вездесу́щ бо єси́ Ти, і нічто́ не мо́жеть от Тебе́ утаї́тися, — воі́стину же ду́хом і житіє́м мої́м. О́браз і подо́біє Твоє́ помрачи́х во мні: уподо́бихся же па́че па́дшим духово́м, і́мже і преда́х себі́. О, могу́ ли поми́слити от нача́ла ми́ра би́ти подо́бна мні грі́шному? Го́рше самі́х христоуби́йць аз, окая́нний, согріши́х. Та́ко удали́вся Тебі́, достиго́х і до сея́ темни́ці, соде́яхся, і́менем і житіє́м мої́м, престу́пник. Но Го́споди, Го́споди! Оста́вих Тя, не оста́ви мене́. Не отврати́ лиця́ Твоєго́ от мене́, я́ко скорблю́. Не попусти́ мні поги́бнути со беззако́ньми мої́ми, а́ще і не досто́їн єсьм поми́лован от Тебе́ би́ти. Поми́луй м'я, Бо́же, по вели́цій ми́лості Твоє́й! І́ми же то́кмо ві́си судьба́ми, спаси́ м'я, многогрі́шнаго. Я́ко Ти єси́, Бо́же, Бог ка́ющихся, і Тебі́ сла́ву возсила́ю, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."],"h":"Молитва 2, до Господа"},{"ps":["Милосе́рдний і многоми́лостивий Бо́же, проро́ка Даниї́ла во рві льви́нем і му́чеников Свої́х в темни́цях благода́тію не оста́вивий, но а́нгела укріпля́ющаго їм посила́вий, сла́вно Твоє́ ми́лостивноє ко мні смотре́ніє, преклоня́ю колі́на се́рдця моєго́ пред вели́чеством Твоєя́ бла́гости і смире́нно прошу́ Тя: не отри́ни моли́тви моєя́, но я́коже апо́столу Па́влу а́нгела мні посли́, укріпля́ющаго і наставля́ющаго м'я, окая́ннійшаго, на за́повіді Боже́ственния Твоя́. Досто́йноє по ді́лом свої́м приє́млю, не посрами́ моєго́ к Тебі́ упова́нія, но сотвори́ м'я христия́нином, правоше́ствующим путе́м за́повідей Твої́х. Ти бо єси́ упова́ніє всіх христия́н і вся содержа́щий Госпо́дь Ісу́с Христо́с і Тя прославля́єм во ві́ки. Амі́нь."],"h":"Молитва 3"}],"notes":[]},{"u":"Тропар перед відплиттям у плавання","e":"Troparion before Setting Out on a Voyage","secs":[{"ps":["К Тебі́, Спа́се, прибіга́ющих / і от Твоєя́ всеси́льния десни́ці по́мощі і благослове́нія, / я́ко от Творця́ і Влади́ки і́щущих, не пре́зри; / но я́коже іногда́ на мо́рі / сло́вом тишину́ апо́столом свої́м по́дал єси́, / і ни́ні ти́хоє і безм'яте́жноє пла́ваніє, со здра́вієм їм да́руй, / моли́твами Богоро́диці, // Єди́не Человіколю́бче.","Сла́ва Отцю́, і Си́ну, і Свято́му Ду́ху."]}],"notes":[]},{"u":"Молитва про зміцнення в Православній вірі й єдності","e":"Prayer for Strengthening in the Orthodox Faith and Unity","secs":[{"ps":["Го́споди, утверди́ во ві́рі сей се́рдце моє́ і сердця́ всіх правосла́вних христия́н; сей ві́ри і сего́ ча́янія жи́ти досто́йно вразуми́; соєдини́ во ві́рі сей все вели́кіє о́бщества христия́нскиє, бі́дственно отпа́дшиє от єди́нства Свято́й Правосла́вной Кафоли́чеськой Це́ркві, я́же єсть Ті́ло Твоє́ і єє же Глава́ єси́ Ти і Спаси́тель Ті́ла; низложи́ горди́ню і противле́ніє учи́телей їх і послі́дующих їм; да́руй їм се́рдцем уразуме́ть і́стину і спаси́тельность Це́ркві Твоє́й і нелі́ностно єй соєдини́ться; совокупи́ Твоє́й Свято́й Це́ркві і недугу́ющих неві́жеством, заблужде́нієм і упо́рством раско́ла, сломи́в си́лою благода́ті Ду́ха Твоєго́ упо́рство їх і противле́ніє І́стині Твоє́й, да не поги́бнуть лю́ті в своє́м противле́нії, я́коже Коре́й, Дафа́н і Авіро́н, проти́вившієся Моїсе́ю і Ааро́ну, раба́м Твої́м.","К сей ві́рі привлеци́ все язи́ци, населя́ющиє зе́млю, да єди́ним се́рдцем і єди́ними усти́ все язи́ци просла́в'ять Тя, Єди́ного всіх Бо́га і Благоді́теля; в сей ві́рі і нас всіх соєдини́ ду́хом кро́тости, смире́нія, незло́бія, простоти́, бесстра́стія, терпі́нія, долготерпі́нія, милосе́рдія, соболе́знованія і сора́дованія.","Амі́нь."]}],"notes":[]},{"u":"Молитва в маловірстві","e":"Prayer in Little Faith","secs":[{"ps":["Благодарю́ Тя, ми́лостивий Го́споди, я́ко яви́л ве́ліє попече́ніє о душе́ моє́й, да́руя єй благо́є і спаси́тельноє уче́ніє Це́ркві Своє́й свято́й. Не посрами́ же ві́ру мою́, но па́че приведи́ м'я ко спаси́тельному Твоєму́ Го́рнему Ца́рствію. Сози́жди в душе́ моє́й Ца́рствіє Своє́ і сподо́би в нем неісхо́дно пребива́ти, да не во осужде́ніє і поги́бель бу́дуть мні Твої́ за́повіді, но во ісправле́ніє, оставле́ніє гріхо́в і во ві́чную жизнь по сла́внім Твоє́м прише́ствії, амі́нь."]}],"notes":[]},{"u":"Молитва з книги «Щирі оповіді мандрівника» про дарування віри","e":"Prayer from “The Way of a Pilgrim” for the Gift of Faith","secs":[{"ps":["Милосе́рдий Го́споди! Да бу́деть во́ля Твоя́, хотя́щая всім спасти́сь і в ра́зум і́стини прийдти́!","Спаси́ і сохрани́ раба́ Твоєго́ (і́м'я), прийми́ сію́ моли́тву мою́, я́ко вопль любві́, запове́данной Тобо́ю!"]}],"notes":[]},{"u":"Ікос преподобному Мартініану Кесарійському (у блудній брані)","e":"Oikos to St Martinian of Caesarea (in Battle with Lust)","secs":[{"ps":["От коне́ць да́же до коне́ць про́йде віща́ніє кра́сних доброді́телей і Боже́ственних по́двиг твої́х: млад сий во́зрастом, в пусти́нях возжела́л єси́ пожи́ти, пі́нія Христу́, псалми́ і моли́тви воспуща́я при́сно: день же і нощ возраста́я в болі́зніх і слеза́х, чи́сті житіє́ твоє́ сконча́л єси́ і, му́дре, злонача́льнаго посрами́л єси́, ти бо змі́я попра́л єси́."]}],"notes":[]},{"u":"Молитви про бачення своїх гріхів","e":"Prayers for Seeing One’s Own Sins","secs":[{"ps":["Го́споди, даждь мі по́мисл іспові́данія гріхо́в мої́х.","Го́споди, да́руй мі зрі́ти моя́ прегріше́нія і не осужда́ти бра́та моєго́.","Го́споди! Даждь нам зрі́ти согріше́нія на́ша, да ум наш, весь ко внима́нію со́бственним на́шим прегріше́нієм привлече́нний, прегріше́нія бли́жніх ви́діти преста́неть, і та́ко вся бли́жняя благи́ми да уви́дить. Даждь се́рдцю на́шему па́губноє попече́ніє о не́мощіх бли́жняго оста́вити, вся же попече́нія во єди́но попече́ніє о стяжа́нії чистоти́ і святи́ні, Тобо́ю нам заповеданней і угото́ванній, совокупи́ти. Даждь нам, ри́зи душе́вния осквернившим, па́ки ти́я убіли́ти: би́ша у́бо омити уже́ Креще́нія вода́ми, ни́ні же, по оскверне́нії, тре́бують сле́зними вода́ми оми́тися. Даждь нам узрі́ти, во сві́ті благода́ті Твоєя́, многообра́зния неду́ги, в нас живу́щия, духо́вния движе́нія в се́рдці потребляющия, движе́нія кров'яная і плотяная, ца́рствію Бо́жию вражде́бная, во о́ноє вводя́щая. Даждь нам ве́лій дар покая́нія, ве́ліїм да́ром зрі́нія гріхо́в свої́х предшествуємий і ражда́ємий. Охрани́ ни си́ми велицими да́ри на путі́ на́шем к Тебі́ і даждь нам Тебе́ дости́гнути, сознающих себі́ грешниками призива́ющаго і мнящих себі́ пра́ведники би́ти отвергающаго, да славосло́вим ві́чно во блаже́нстві ві́чнім Тебе́, Єди́наго І́стиннаго Бо́га, пліне́нних Іскупи́теля, поги́бших Спаси́теля."]}],"notes":[]},{"u":"Молитва при вході в новий дім","e":"Prayer on Entering a New House","secs":[{"ps":["Бо́же Спаси́телю наш, ізво́ливий под сінь Закхе́єву вни́ти, і спасе́ніє тому́, і всему́ до́му того́ би́вий: Сам і ни́ні зді жи́ти восхоті́вшия, і на́ми недосто́йними мольби́ Тебі́ і моле́нія принося́щия, от вся́каго вре́да соблюди́ невреди́ми, благословля́я тіх зді жили́ще, і ненаві́тен тіх живо́т сохраня́яй. Амі́нь."]}],"notes":[]},{"u":"Молитва до Бога під час зливових дощів","e":"Prayer to God in Time of Torrential Rains","secs":[{"ps":["Досто́йная ка́знем сотвори́хом, і пра́веден суд Твой пости́же нас, Го́споди, но пощади́, пощади́ люде́й согріши́вших, і отврати́ гнів Твой, пра́ведно на нас дви́жимий, в покая́нії к Тебі́ припа́даєм і смире́нно мо́лим Тя, усли́ши і поми́луй.","Да не потопи́ть нас, Го́споди, бу́ря водна́я, і да не растли́ши зе́млю, і гла́дом да не умори́ши нас люде́й Твої́х, но я́ко Благ уста́ви водно́є лія́ніє і теплоті́ со́лнечній возсія́ти на землі́ я́ко Всемогу́щий повели́, прилі́жно мо́лимся Тебі́, Царю́ Пресвяти́й, усли́ши і поми́луй.","Ни́щих ра́ди люде́й Твої́х і ското́в, мра́чному возду́ху і те́мной мглі рази́тися, і луча́м со́лнечним возсія́ти повели́, Всеще́дрий Го́споди, да не безвре́менно сконча́ємся, мо́лимся Тебі́, ско́ро усли́ши і поми́луй.","Спаси́ нас, Го́споди, от мра́чнаго злорастворе́ннаго возду́ха, от безвре́менния мокроти́ і те́мния мгли, да не ісче́знуть в суєті́ дні́є на́ші, і лі́та на́ша во воздиха́ніїх, но пом'яни́ заві́т Твой, і́же к Но́ю, і сотвори́ с на́ми по ми́лості Твоє́й, сокруше́нним се́рдцем мо́лимся Тебі́, усли́ши і поми́луй.","В ско́рбі і печа́лі на́шей к Тебі́, Го́споду Бо́гу на́шему, умиле́нно вопіє́м: да при́йдеть к Тебі́ моли́тва на́ша, да ізи́деть із істлі́нія жизнь на́ша, і да не ісче́знеть безвре́менно, ми́лостивно усли́ши глас ни́щих люде́й Твої́х, і человіколю́бно поми́луй.","Не на дугу́, ю́же в зна́меніє заві́та на о́блаціх поста́вил єси́, Го́споди, но на Твоя́ щедро́ти взира́єм, і Твою́ ми́лость привлещи́ і́щем, к Тебі́ бога́тому в ми́лості і безмі́рному в щедро́тах, се́рдцем сокруше́нним мо́лимся: пода́ждь нам ме́рноє, і плодоно́сноє ве́дро с благорастворе́нним возду́хом, і ско́ро я́ко Щедр усли́ши і поми́луй."]}],"notes":[]},{"u":"Молитва святим про визволення воїнів з полону","e":"Prayer to the Saints for the Deliverance of Soldiers from Captivity","secs":[{"ps":["Мо́лим вас ми, недосто́йнії: укріпі́те во́їнов [во́їна] [і́м'ярік], в пліне́нії су́щих [су́щаго], от уз вра́жиїх їх [єго́] ізба́віте, вся́каго зла́го обстоя́нія свободи́те і на спасе́нія стезі́ напра́віте, да, в до́ми своя́ возврати́вшеся, просла́в'ять [дом свой возврати́вся, просла́вить] І́стиннаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха і ва́ше ми́лостивоє предста́тельство во ві́ки віко́в. Амі́нь.","Мо́лим вас ми, недостойниє: укріпі́те во́їнов (во́їна) [і́м'я], в пліне́нії находя́щихся (находящегося), от уз вра́жеських їх (єго́) ізбавте, от всіх тяжелих невзгод освободіте і на путь спасе́нія направте, да, в до́ма свої́ возвратившись (в дом свой возвратившись), просла́вить Істинного Бо́га, Отця́ і Си́на і Святого Ду́ха і ва́ше ми́лостивоє засту́пничество во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитви священників, що готуються до звершення Божественної Літургії","e":"Prayers of Priests Preparing to Celebrate the Divine Liturgy","secs":[{"ps":["Архієре́ю І́стинний Ісу́се Христе́, принеси́й Себе́ Бо́гу Отцю́ на олтарі́ кре́стном же́ртву чи́сту, непоро́чну, о нас, грі́шних, і да́вий нам Ті́ло Твоє́ я́сти, і Кров Твою́ пи́ти, положи́вий та́їнство в си́лі Ду́ха Свята́го, глаго́ля сіє́: єли́жди а́ще твори́те, в Моє́ воспомина́ніє творі́те: молю́ чрез Кров Твою́ дража́йшую, ве́лію спасе́нія на́шего ці́ну, молю́ чрез сію́ ди́вную і неісповіди́мую любо́в, є́юже нас недосто́йних та́ко возлюби́л єси́, я́ко оми́л єси́ нас от гріхо́в на́ших Кро́вію Твоє́ю: научи́ м'я недосто́йнаго раба́ Твоєго́, єго́же при іни́х Твої́х дарова́ніях, в чин свяще́нства, не по ді́лом мої́м, но по єди́ной Твоє́й благоізво́лил єси́ призва́ти ми́лості: научи́ м'я Ду́хом Твої́м толи́кую та́йну соверша́ти, сицево́ю че́стію і благогові́нієм, сицеви́м благоче́стієм і стра́хом, ї́миже досто́їть твори́ти. Сотвори́ м'я, Го́споди Ісу́се Христе́, благода́тію Твоє́ю всегда́ о вели́честві та́йни сея́ ві́ровати і разумі́ти, чу́вствовати, і тве́рдо держа́ти, глаго́лати і ми́слити Тебі́ подоба́ющая, і душі́ моє́й поле́зная. Да вни́деть в се́рдці моє́ Дух Твой благи́й, глася́й безгла́сні, глаго́ляй вся́ку і́стину толи́ких та́їнств, я́же углуби́шася зіло́ і боже́ственним прикрове́на кро́вом. Мно́гаго ра́ди милосе́рдія Твоєго́ благоволи́ мні, ни́ні і всегда́ чи́стим се́рдцем і ми́слію, слу́жби соверша́ти священноді́йствіє. Очи́сти се́рдце от нечи́стих, ме́рських, пра́здних, і вре́дних помишле́ній. Огради́, святи́х а́нгел ві́рним хране́нієм і крі́пким ополче́нієм: да вразі́ всіх благ посра́млені отбіжа́ть си́лою толи́каго та́їнства, і руко́ю свята́го а́нгела Твоєго́, отста́ви от мене́, Христе́ мой, і от всіх рабо́в Твої́х ду́ха горди́ні, тщесла́вія, за́висти, я́рости, блуда́, нечистоти́, неві́рія і хули́, да постидя́ться гоня́щії нас, і да поги́бнуть погуби́ти нас тща́щіїся.","Царю́ сил, чистоти́ і цілому́дрія Люби́телю, Бо́же, росо́ю сви́ше благослове́нія Твоєго́, погаси́ в пло́ті моє́й весь пла́мень стра́стний, я́ко да живе́ть во мні всеці́лая душі́ і ті́ла чистота́, с про́чими дарова́нії Твої́ми Тебі́ в пра́вді прия́тними: да ті́лом нескве́рним, і се́рдцем чи́стим, возмогу́ Тебі́ принести́ же́ртву хвале́нія, с коли́ким се́рдця сокруше́нієм, слез ізлія́нієм, с каково́ю по́честію і стра́хом, в коли́кой пло́ті і ду́ха чистоті́, сіє́ пренебе́сноє боже́ственноє до́лжно єсть наверша́тися приноше́ніє, іді́же Ті́ло Твоє́ суще́ственні я́сться, і Кров Твоя́ суще́ственні піє́ться, іді́же го́рняя до́льним совокупля́ються, іді́же самоли́чні предстоя́ть а́нгели, іді́же ієре́й і же́ртва чуде́сні і неізрече́нні, Ти Сам предложе́нний. І кто досто́йні сіє́ соверша́ти возмо́жеть, а́ще не Ти Сам, Всемоги́й Го́споди, принося́щаго досто́йна сотвори́ши? Вім, і і́стинно ізві́стен єсьм, і сіє́ милосе́рдію Твоєму́ іспові́дую, я́ко нісьм досто́їн мно́жества ра́ди гріхо́в і безчи́сленних прегріше́ній мої́х к толи́ким та́йнам приступи́ти, но вім воі́стину, і ві́рую от всего́ се́рдця, і усти́ іспові́дую, я́ко си́лен м'я єси́ удосто́їти, Сам Єди́н, в беззако́ніїх зача́таго і рожде́ннаго моги́й очи́стити. Ра́ди сего́ всемогу́тства Твоєго́ Тебі́ молю́: благоволи́ мні грі́шному небе́сную сію́ же́ртву со стра́хом і тре́петом, чи́стою со́вістію, слез ізлія́нієм, в ра́дості духо́вной і весе́лії боже́ственном приноси́ти: да ощути́ть ум мой блаже́нную прише́ствія Твоєго́ сла́дость і ополче́ніє святи́х а́нгел Твої́х о́крест мене́:","Аз бо, Го́споди, помина́я спаси́тельния Твоя́ Стра́сті, ко олтарю́ Твоєму́ приступа́ю, а́ще і недосто́йний, да принесу́ Тебі́ же́ртву от Тебе́ пре́данную, і приноси́тися во воспомина́ніє Твоє́ о спасе́нії на́шем уста́вленную. Прийми́ у́бо сію́, молю́ Тя, Бо́же мой, о Це́ркві Святі́й Твоє́й, і о всіх лю́діх, ї́хже Честно́ю Твоє́ю снабді́л єси́ Кро́вію: і зане́же м'я грі́шника между́ Тобо́ю і о́німи сре́дственна хода́тая би́ти восхоті́л єси́, а́ще благи́х діл во мні свиді́тельства не обріта́єши, служе́нія примире́нія вві́реннаго мні да не отрече́шися: я́ко да не моєго́ ра́ди недосто́їнства, ціни́ спасе́нія своєго́ отщетя́ться, ї́хже ра́ди Сам спаси́тельная же́ртва і іскупле́ніє ізво́лил єси́ би́ти.","Приношу́ у́бо, Го́споди, [а́ще благоволи́ши ми́лостивно призрі́ти] ско́рбі люде́й, пліне́нних воздиха́нія, страда́нія убо́гих, ну́жди путеше́ствующих, немощни́х ско́рбі, ста́рих не́мощі, рида́нія младе́нець, обі́ти дів, моли́тви вдов, і сиро́т умиле́ніє. Ти бо ми́луєши вся, і нічто́же от Тебе́ созда́нних презира́єши. Пом'яни́, кий єсть соста́в наш, я́ко Ти Оте́ць наш єси́: не прогні́вайся на ни зіло́, ні утро́би щедро́т Твої́х затвори́ от нас Го́споди, не бо в пра́вдах на́ших ізлива́єм моли́тви на́ша пред лице́м Твої́м, но в щедро́тах Твої́х мно́гих. Отими́ от нас, Го́споди, беззако́нія на́ша, і огне́м Свята́го Твоєго́ Ду́ха в нас ми́лостивні іспепели́: отими́ се́рдце ка́менноє от пло́ті на́шея, і даждь се́рдце плотяно́є боя́щеєся Тебе́, лю́б'ящеє, почита́ющеє, Тебі́ послі́дующеє, і Тобо́ю пита́ющеєся. Про́сим, Влади́ко, щедро́ти Твоя́, да лице́м сві́тлим на достоя́ніє Твоє́, і́мені Твоєму́ свято́му служе́нія ожида́ющеє, воззрі́ти благоволи́ши: і да ниєди́наго же моли́тва, ниєди́наго проше́ніє отринове́нно бу́деть, Ти нас научи́ моли́тися, є́же і Сам гото́в сли́шиши, і проси́мая ми́лостивні ісполня́єши.","Мо́лим Тя, О́тче Святи́й, о душа́х ві́рних преста́вльшихся, я́ко да бу́деть їм во ізбавле́ніє, спасе́ніє, отра́ду, і ві́чноє весе́ліє сіє́ вели́коє благоче́стія та́їнство: Го́споди Бо́же мой, бу́ди їм днесь всеці́лоє і соверше́нноє утіше́ніє, от Тебе́ Хлі́ба І́стиннаго, Жива́го, с небесе́ сше́дшаго, і даю́щаго живо́т ми́рові, от пло́ті Твоєя́ Святи́я, А́гнця нескве́рна, взе́млющаго гріхи́ ми́ра. Напо́й їх пото́ком бла́гости Твоєя́, от прободе́ннаго Твоєго́ ребра́ на Кресті́ істе́кшим, да тім возвеселе́ни, ра́дуються во хвалі́ і сла́ві Твоє́й Свято́й.","Молю́ Го́споди, бла́гость Твою́: да при́йдеть на хліб сей і ча́шу сію́ ісполне́ніє Божества́ Твоєго́, да сни́деть та́кожде, Го́споди, Свята́го Твоєго́ Ду́ха о́браз неви́димий, і непостижи́мая сла́ва, я́коже пре́жде на же́ртви отце́в схожда́ше, і́же і приноше́нія сія́ на́ша, да сотвори́ть Ті́ло і Кров Твою́, і мене́ недосто́йнаго служи́теля Твоєго́ толи́коє соверша́ти научи́ть та́їнство: я́ко да благоприя́тні і ми́лостивні при́ймеши от рук мої́х же́ртву во спасе́ніє всіх живи́х і ме́ртвих.","Молю́ Тя, Го́споди, сама́го ра́ди Святи́х Ті́ла і Кро́ве Твоєя́ та́їнства, ї́миже всегда́ в хра́мі Твоє́м пита́ємі і напая́ємі, очища́ємі, освяща́ємі і обожа́ємі бива́єм, да си́лою Твоє́ю укріпле́н, благо́ю со́вістію ко олтарю́ Твоєму́ приходя́, сія́ небе́сная та́їнства імі́ю в себі́ в живо́т і спасе́ніє, по словесі́ свято́му Твоєму́: Хліб, єго́же Аз дам, Плоть Моя́ єсть, Ю́же Аз дам за живо́т ми́ра: яди́й М'я і той жив бу́деть Мене́ ра́ди. Хлі́бе сладча́йший, уврачу́й устні́ се́рдця моєго́, да чу́вствую во мні любве́ Твоєя́ сла́дость: ісціли́ всяк неду́г, да кромі́ Тебе́, нікоєя́же пожела́ю красоти́. Хлі́бе чисті́йший, вся́кия сла́дости і благово́нія преіспо́лненне, вни́ди в се́рдці моє́, і сла́достію благово́нія Твоєго́ напо́лни вну́тренняя душі́ моєя́. Тобо́ю пита́ються а́нгели на небесі́ преізоби́льно: да наси́титься по си́лі своє́й Тобо́ю і пришле́ць челові́к на землі́. Хлі́бе святи́й, Хлі́бе живи́й, Хлі́бе вожделі́нне, сходя́й с небесе́, і дая́й живо́т ми́рові, вни́ди в се́рдці моє́, і очи́сти м'я от вся́кия скве́рни пло́ті і ду́ха: вни́ди в ду́шу мою́ вніу́ду і внутру́ду освяща́я і просвіща́я: бу́ди моє́й хране́ніє всегда́шнєє душі́, і ті́ла здра́віє. Отжени́ от мене́ находя́щих на м'я, да біжа́ть от лиця́ Твоєго́ ненави́дящії м'я: да Тобо́ю огражде́н, с Тобо́ю прейду́ во ві́чноє Твоє́ ца́рствіє, іді́же не покрове́нні, но лице́м к лицю́ Тебе́ у́зрим, єгда́ преда́си ца́рство Бо́гу і Отцю́, да бу́деть Бог вся́чеськая во всіх. До ни́ні а́лчу і жа́жду, но тогда́ наси́щуся, внегда́ яви́ть мі ся сла́ва Твоя́, в не́йже ца́рствуєши со Отце́м і Святи́м Ду́хом, во ві́ки, амі́нь."]}],"notes":[]},{"u":"Молитви св. Іоанна Кронштадтського про любов до ближніх і сміливість перед Богом","e":"Prayers of St John of Kronstadt on Love of Neighbour and Boldness before God","secs":[{"ps":["Го́споди, возмо́жно Тебі́ сді́лать (то) і (то) рабу́ Твоєму́ (і́м'я); сотвори́ єму́ сіє́, і́бо і́м'я Тебі́ – благи́й Человіколю́бець і Всемогу́щий. А́ще ми, лука́ва су́ще, умеєм дая́ніє бла́га дая́ти не то́кмо ча́дам, но і чужи́м, кольми́ па́че Ти да́си всевозможния бла́га прося́щим у Тебе́. Благи́й Человіколю́бче! І́же твар єди́ним сло́вом соді́лавий і із нея́ челові́ка созда́вий, посіти́ же неізрече́нним Твої́м человіколю́бієм па́дшаго раба́ Твоєго́, я́ко да не поги́бнеть до конця́ ді́ло руки́ Твоєя́. Амі́нь.","Даждь мі, Го́споди, люби́ти вся́каго бли́жняго моєго́, как себ'я́, всегда́, і ні із-за чего́ на него́ не озлоблятися і не рабо́тати дия́волу.","Даждь мі расп'я́ти моє́ самолю́біє, го́рдость, любостяжа́ніє, малові́ріє і про́чія стра́сті.","Да бу́деть нам і́м'я: взаїмная любо́в; да ві́руєм і упова́єм, что для всіх нас все Госпо́дь; да не пече́мся, не беспокоїмся ні о чем; да будеш Ти, Бо́же наш, єди́ним Бо́гом се́рдця на́шего, і, кромі́ Тя, нічто́.","Да бу́дем ми между́ собо́ю в єдине́нії любві́, я́коже подоба́єть, і все разделяющеє нас друг от дру́га і от любві́ отлуча́ющеє да бу́деть у нас в презрі́нії, как прах, попира́ємий нога́ми. Бу́ди! Бу́ди! Амі́нь.","Госпо́дь пасе́ть м'я, і нічто́же м'я лиши́ть (Пс.22:1)."]}],"notes":[]},{"u":"Молитви свт. Тихона Задонського про вмиротворення біснуючої душі","e":"Prayers of St Tikhon of Zadonsk for Calming a Raging Soul","secs":[{"ps":["Поми́луй м'я Го́споди, Си́не Бо́жий: душа́ моя́ злі бісну́ється. Го́споди, помози́ мі. Даждь мі, да наси́щуся і аз, я́ко пес от крупи́ць, па́дающих от трапе́зи рабо́в Твої́х. Амі́нь.","Поми́луй м'я, Го́споди, Си́не Бо́жий, Си́не Дави́дов по пло́ті, я́коже поми́ловал єси́ ханане́ю: душа́ моя́ злі бісну́ється гні́вом, я́ростію, по́хотію зло́ю і про́чими па́губними страстьми́. Го́споди! Помози́ мні, вопію́ Тебі́, не на землі́ ходя́щему, но одесну́ю Отця́ на небесі́х сідя́щему. Єй, Го́споди! Даждь мні се́рдце ві́рою і любо́вію послі́довати Твоєму́ смире́нію, бла́гости, кро́тости і долготерпі́нію, да і во ві́чном Твоє́м Ца́рствії сподо́блюся причаща́тися трапе́зи рабо́в Твої́х, ї́хже ізбра́л єси́. Амі́нь."]}],"notes":[]},{"u":"Молитви до Христа, взяті зі Святого Євангелія (свт. Тихон Задонський)","e":"Prayers to Christ Taken from the Holy Gospel (St Tikhon of Zadonsk)","secs":[{"ps":["«Си́не Бо́жий, Ісу́се Христе́, яви́вийся во смиренной на́шей пло́ті на землі́, і посеявий до́броє ві́ри сі́м'я на селі́ ми́ра сего́! Огради́ стра́хом Твої́м се́рдце моє́, да не приходя́ лука́вий восхища́єть посеянноє Сло́ва Твоєго́ сі́м'я, і очи́сти се́рдце моє́ от те́рній печа́лі ві́ка сего́, ле́сти, бога́тства і вся́кия суєти́, і сотвори́ то́є до́брою земле́ю к прия́тію Божественного Твоєго́ Сло́ва, да сотворю́ плод ві́ри і імі́ю часть со ізбра́нними Твої́ми, і́же плод прино́сять Тебі́ о́во сто, о́во шестьдеся́т, о́во три́десять, – я́ко благослове́н єси́ со Отце́м і Святи́м Твої́м Ду́хом вовеки, амі́нь»."],"h":"1. Із притчі про сівача (Мф. 13:3–8)"},{"ps":["«Поми́луй м'я, Го́споди Си́не Бо́жий, Си́не Дави́дов по пло́ті, я́коже поми́ловал єси́ ханане́ю: душа́ моя́ злі бісну́ється гні́вом, я́ростію, по́хотію зло́ю і про́чіїми па́губними страстьми́. Го́споди! Помози́ мні, вопію́ Тебі́, не на землі́ ходя́щему, но одесну́ю Отця́ на небесі́х сідя́щему. Єй, Го́споди! Даждь мні се́рдце ві́рою і любо́вію послі́довати Твоєму́ смире́нію, бла́гости, кро́тости і долготерпі́нію, да і во ві́чном Твоє́м ца́рствії сподо́блюся причаща́тися трапе́зи рабо́в Твої́х, ї́хже ізбра́л єси́. Амі́нь»."],"h":"2. Із розповіді про хананеянку (Мф. 15:22–28)"},{"ps":["«Собезнача́льний Отцю́ і Ду́ху Сло́ве, нас ра́ди, челові́к, і на́шего ра́ди спасе́нія от Ді́ви роди́вийся і на землі́ пожи́вий! Сподо́би м'я вкуси́ти бла́гости Твоєя́, ю́же святи́є Твої́, лю́б'ящії і почита́ющії Тя, і ни́ні вкуша́ють, стра́нствующе в плаче́вной ми́ра сего́ юдо́лі, – і зрі́ти присносу́щний світ Твой у́мним о́ком, єго́же святи́м Твої́м ученико́м показа́л єси́ в Преображе́нії святі́йшия Пло́ті Твоєя́, да, ни́ні ві́рою зря, пото́м лице́м к лицю́ сподо́блюся ви́діти сла́ву Твою́, і со ізбра́нними Твої́ми хвали́ти Тя і Безначального Твоєго́ Отця́ і Свята́го Ду́ха. Амі́нь»."],"h":"4. Із розповіді про Преображення (Мф. 17:1–9)"},{"ps":["«Си́не Бо́жий, Сві́те ві́чний, і дая́й всім світ! Поми́луй м'я, просвіти́ о́чі се́рдця моєго́, мгло́ю гріхо́в і страсте́й омраче́нная, я́коже просвіти́л єси́ сліпи́х, возопивших к Тебі́. Да отве́рзуться і мої́ о́чі серде́чная, да узрю́ Тя, Сві́та незаходи́маго, і ві́рою і любо́вію послі́дую Тебі́, мене́ ра́ди, окая́ннаго, ходи́вшему по землі́. Амі́нь»."],"h":"6. Із розповіді про сліпців (Мф. 20:30–34)"},{"ps":["«Ісу́се Си́не Бо́жий, Спаси́телю і Обнови́телю ми́ра, зло́бою гріхо́вною обветша́вшаго! Обнови́ мене́ благода́тію Животворя́щаго Ду́ха Твоєго́. Дай мні ум разумі́ти си́лу спаси́тельнаго прише́ствія Твоєго́. Дай мні се́рдце люби́ти Тя – ві́чную любо́в, утіше́ніє і ра́дость святи́х. Дай мні о́чі непреста́нно зрі́ти стра́сті Твоя́. Дай мні у́ші сли́шати свято́є Сло́во Твоє́. Дай мні уста́ глаго́лати Тебі́ уго́дная, мні і бли́жнему поле́зная. Дай мні но́зі ходи́ти по стезі́ за́повідей Твої́х; і все моє́, молю́ Тя, отими, і пода́ждь Своє́; возьми́ ве́тхоє, і пода́й но́воє все, я́ко Ти єси́ творя́й вся, і без Тебе́ «не мо́жем твори́ти нічесо́же» (Ін.15:5), я́ко благослове́н єси́ во ві́ки. Амі́нь»."],"h":"8. Молитва про духовне оновлення"}],"notes":[]},{"u":"Молитва під час лиха й нападу ворогів","e":"Prayer in Calamity and Attack by Enemies","secs":[{"ps":["Господи, Всемогутній Боже, Царю всіх царюючих і Господи всіх господарюючих, Ти, Який сказав, що й волосина з голови не впаде в нас без волі Твоєї, Ти, що припиняєш війни до краю землі, ламаєш лук, трощиш спис, палиш вогнем колісниці! Будь нашою допомогою, захистом і твердинею, скелястою горою й огорожею від ворогів. Не покинь спадщини Твоєї, що зветься святим ім’ям Христовим. Нехай звеличиться слава Твоя на висотах і по всьому світі, нехай буде на землі мир і благовоління. Не допусти руйнувати й спустошувати церкви й училища, землі й народи, де перебуває слава Твоя. Даруй усім християнським владам і підданим постійний мир і злагоду. Озброй нас могутністю Твоєю, бо Тобою можемо ми розбити полки. Зодягни нас силою Твоєю й зроби, щоб ми зміцніли Тобою і могутністю сили Твоєї. Амінь."]}],"notes":[]},{"u":"Молитва в наругах і нерозумінні","e":"Prayer in Reproach and Misunderstanding","secs":[{"ps":["Вічний Боже й Отче! Даруй мені Твого Духа сили, щоб Він зміцнив мене в моїй немочі, утвердив і зробив непохитним, щоб ні скорбота, ні гоніння, ні нагота не відлучали мене від любові Твоєї, а щоб я все переборював заради Того, Хто мене полюбив. Даруй, щоб у всьому я виявляв себе як служитель Христів, з великим терпінням у бідах, у нуждах, у тісних обставинах, у ранах, у в’язницях, у трудах, у недосипанні, у постах, з чистотою, зі знанням, із довготерпінням, із добротою, зі Святим Духом, з нелицемірною любов’ю, зі словом істини, із силою Божою; щоб я наслідував Його і в честі, і в безчесті, серед докорів і похвал; охоче з Ним і заради імені Його дозволяючи тут наді мною глузувати, бо Він, якщо я залишуся вірним до смерті, увінчає мене вінцем життя. Амінь."]}],"notes":[]},{"u":"Молитва в блюзнірських та інших помислах під час молитви","e":"Prayer against Blasphemous and Other Thoughts at Prayer","secs":[{"ps":["Душу мою відкриваю перед Тобою, Господи! Ти бачиш, що я не хочу таких думок і не схвалюю їх. Усе це сіє ворог. Віджени його від мене!"]}],"notes":[]},{"u":"Про дарування молитви","e":"For the Gift of Prayer","secs":[{"ps":["Господи! Навчи нас молитися. (Лк. 11:1)","Навчи мене, Господи, ревно молитися Тобі з увагою й любов’ю, без яких молитва не буває почута! Нехай не буде в мене недбалої молитви мені на гріх!"]}],"notes":[]},{"u":"Молитва в день Нового року","e":"Prayer on New Year’s Day","secs":[{"ps":["Господи Боже, всіх видимих і невидимих створінь Творче й Будівничий, Ти, що створив часи й роки, Сам поблагослови новий рік, який починається цього дня, що його ми лічимо від втілення Твого заради нашого спасіння.","Дозволь нам провести цей рік і багато наступних у мирі та злагоді з нашими ближніми; зміцни й поширюй Святу Вселенську Церкву, яку Ти Сам заснував і спасенною жертвою Святого Тіла й Пречистої Крові освятив.","Вітчизну нашу вознеси, збережи й прослав; довгі дні, здоров’я, достаток плодів земних і сприятливу погоду дай нам.","Мене, грішного раба Твого, усіх родичів і ближніх моїх та всіх благовірних християн, як істинний наш верховний Пастир, збережи, огороди й на шляху спасіння утверди, щоб ми, ідучи ним після довгого й благополучного життя в цьому світі, досягли Царства Твого Небесного й удостоїлися вічного блаженства з святими Твоїми. Амінь."]}],"notes":[]},{"u":"Молитва в день народження","e":"Prayer on One’s Birthday","secs":[{"ps":["Господи, Боже, Владико всього світу видимого й невидимого.","Від Твоєї Святої волі залежать усі дні й літа мого життя.","Дякую Тобі, премилосердний Отче, що Ти дозволив мені прожити ще один рік; знаю, що за гріхами моїми я недостойний цієї милості, але Ти виявляєш її мені з невимовної Твоєї любові до людей.","Продовж і далі милості Твої до мене, грішного (грішної); подовж життя моє в чесноті, спокої, здоров’ї, у мирі з усіма родичами й злагоді з усіма ближніми.","Подай мені достаток плодів земних і все, що потрібне для задоволення моїх потреб.","Особливо ж очисть совість мою, зміцни мене на шляху спасіння, щоб я, ідучи ним після багатолітнього життя в цьому світі, перейшовши в життя вічне, удостоївся (удостоїлася) стати спадкоємцем (спадкоємицею) Царства Твого Небесного.","Сам, Господи, поблагослови рік, який я починаю, і всі дні життя мого.","Амінь."]}],"notes":[]},{"u":"Молитва св. Іоанна Золотоустого в недоумінні, як учинити","e":"Prayer of St John Chrysostom in Perplexity","secs":[{"ps":["Дай, Господи, моїй недостойності благодать розуміння, щоб розпізнавати угодне Тобі, а для мене корисне, і не тільки розпізнавати, але й звершувати, щоб не захоплюватися й не прилипати до марного, щоб співчувати стражденним і бути поблажливим до грішників."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського про дарування лагідності й смирення","e":"Prayer of St John of Kronstadt for Meekness and Humility","secs":[{"ps":["О лагідний і смиренний серцем Творче, Життєдавче, Спасителю, Годівнику й Охоронцю наш, Господи Ісусе! Навчи нас Ти любові, лагідності й смирення Духом Твоїм Святим і зміцни нас у цих найлюбіших Тобі чеснотах, щоб не надималися наші серця від багатих дарів Твоїх, щоб не уявляли ми, ніби ми годуємо, задовольняємо потреби й підтримуємо когось: Ти — спільний усіх Годувальник — годуєш, задовольняєш потреби й береш під опіку; усі під крилами Твоєї доброти, щедрот і людинолюбства задовольняються й спочивають, а не під нашими, бо ми самі маємо потребу ховатися в тіні Твоїх крил — кожної миті нашого життя. Наші очі звернені до Тебе, Бога нашого, як очі рабів на руку господаря, очі рабині на руку господині своєї, доки Ти не змилосердишся над нами. Амінь."]}],"notes":[]},{"u":"Молитва з творінь св. Єфрема Сиріна про допомогу Божу у виправленні життя","e":"Prayer from the Works of St Ephrem the Syrian for God’s Help in Amending One’s Life","secs":[{"ps":["Господи, Боже Вседержителю, згрішив я проти неба й перед Тобою і вже недостойний зватися сином Твоїм, ні називати славне ім’я Твоє грішними устами моїми, бо я зробив себе недостойним неба й землі, розгнівавши Тебе, благого Владику! Недостойний я просити для себе прощення, Господи, бо багато разів обіцяв покаятися — і ставав лжецем, що не виконав обіцянки, багато разів уже підіймав Ти мене, але я знову падав добровільно. Сам на себе виголошую вирок і визнаю, що гідний я всякої кари й муки.","Благаю Тебе, Господи, не відкинь мене від лиця Твого й не відступи від мене, щоб не загинути мені. Нині припадаю до Тебе, благаючи: допоможи мені, що збився зі шляху правди. Вилий на мене щедроти Твої, як на блудного сина, бо я осоромив життя своє, розтринькавши багатство доброти Твоєї. Помилуй мене і не погордуй мною через непотрібне життя моє. Помилуй мене, як митаря, як розбійника: той на землі був усіма відкинутий, але Ти прийняв його й зробив мешканцем раю солодощів.","Милостиво прийми молитву мою про примирення з Тобою і за добротою Твоєю дай мені життя в прихід Твій; і нехай засоромиться лукавий, коли побачить, що мене помилувала правда Твоя. Даруючи прощення, Господи, пошли й силу; наверни мене так, щоб і жити мені за святою волею Твоєю.","Скільки разів відвідував Ти затьмарений мій розум, а я знову повертаюся до гіршого! Увесь тремчу, розмірковуючи про це, і знову перемагає мене гріховна солодкість. Як перелічу всі дари благодаті Твоєї, Господи, які я, жалюгідний, отримав, але обертав і обертаю в ніщо своєю недбалістю! Тисячами дарів сповнював Ти мене, а я, бідний, віддячую Тобі тим, що Тобі осоружне.","Але Ти, Господи, оскільки в Тобі море довготерпіння і безодня милосердя в Тебе, не дозволь зрубати мене, як безплідну смоківницю. Не забирай мене, неготового, не бери не запаливши ще світильника, не вилучай звідси того, хто не має шлюбного одягу, але, як благий Чоловіколюбець, помилуй мене, дай мені час на покаяння і перед страшним, непідкупним престолом Твоїм не став душу мою оголеною, як жалюгідне видовисько безслав’я.","Ти, Господи, Спасителю мій, Сину Бога істинного, як Сам знаєш і як Сам хочеш, єдиною добротою Твоєю, навіть проти мого бажання, наверни мене від гріха, що перебуває в мені, і спаси від загибелі."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського про виправлення життя й утвердження в чеснотах","e":"Prayer of St John of Kronstadt for Amendment of Life and Firmness in Virtue","secs":[{"ps":["Скільки разів, о Владико Господи Ісусе, оновлював Ти легковажно зіпсоване гріхами моїми єство моє! Нема тому ні числа, ні міри! Скільки разів Ти виймав мене з печі, що палає в мені всередині, з печі різноманітних пристрастей, із прірви зневіри й розпачу! Скільки разів самим іменем Твоїм, яке я з вірою призиваю, оновлював Ти моє серцеве тління! Скільки разів звершив це через животворні Тайни. О Владико! Милостям Твоїм до мене, грішного, воістину нема ні числа, ні міри. Що ж я принесу Тобі або що віддам Тобі за безмірні Твої до мене благодіяння, Ісусе, Життя моє і Полегкосте моя! Нехай буду я обачним на шляхах моїх за благодаттю Твоєю, бо Тобі приємні всі обачні на шляху, як Ти Духом Своїм устами батька нашого Давида сказав; постараюся бути вірним Тобі, смиренним, лагідним, нероздратованим, незлобивим, довготерпеливим, працьовитим, милостивим, щедрим, нехтивим до наживи, слухняним.","Господи, Сило всемогутня! Утверди немічну душу мою в усякій чесноті! На непорушній скелі заповідей Твоїх утверди слабке до всякого добра серце моє! Господи! І я щодня на досвіді пізнаю, що без Тебе я ніщо; що без Тебе не можу чинити ніякого добра; без Тебе одне лише зло в мені в різних його видах; без Тебе я син загибельний. О, найвеличніша Благосте! Сповни добротою Твоєю серце моє! Паче ж усього благаю: даруй мені любити Тебе всім серцем моїм і ближнього мого, як себе. Нехай не буду я злобним, гордим, зарозумілим, неспокійним, але нехай буду незлобивим, смиренним, шанобливим із ніжністю й слухняним."]}],"notes":[]},{"u":"Молитва з творінь свт. Димитрія Ростовського в зневірі","e":"Prayer from the Works of St Demetrius of Rostov in Despondency","secs":[{"ps":["Боже, Отче Господа нашого Ісуса Христа, Отче щедрот і Боже всякої втіхи, що втішаєш нас у всякій скорботі нашій! Утіш кожного скорботного, засмученого, зневіреного, змученого духом зневіри. Адже кожна людина створена руками Твоїми, умудрена премудрістю, звеличена правицею Твоєю, прославлена добротою Твоєю… Але ось відвідані ми нині Отчим Твоїм карінням, короткочасними скорботами! — Ти співчутливо караєш тих, кого любиш, і щедро милуєш, і зглядаєшся на їхні сльози! Отже, покаравши, помилуй і втамуй наш смуток; обрати скорботу на веселощі й радістю розведи смуток наш; виявиш на нас милість Твою, дивний у задумах Владико, Незбагненний у присудах Господи, і благословенний у ділах Твоїх повіки, амінь."]}],"notes":[]},{"u":"Таємна молитва для нестримних у їжі","e":"A Secret Prayer for the Intemperate in Eating","secs":[{"ps":["Також благаю Тебе, Господи, визволи мене від пересичення й солодолюбства і даруй мені у мирі душевному з благоговінням приймати щедрі дари Твої, щоб, споживаючи їх, отримати зміцнення моїх сил душевних і тілесних для служіння Тобі, Господи, у недовгій решті мого життя на землі."]}],"notes":[]},{"u":"Молитва при наклепі й несправедливих утисках","e":"Prayer in Slander and Unjust Oppression","secs":[{"ps":["Ти, Господи, приніс Себе в жертву на хресті заради мого спасіння. Чи можу ж і я ухилитися від тягарів несправедливих суджень людей про мене? Зроби, Господи Ісусе, щоб, згадуючи ті наруги й облуду, яких Ти зазнав за мене, навчилося серце моє терпіння і не тільки без роздратування, а навіть із подякою охоче зносило образи й осуди інших. Про одне благаю Тебе, Господи, не залиш ворогів моїх назавжди в їхній сліпоті, а осяй нарешті й їх променем благодаті Твоєї. Амінь."]}],"notes":[]},{"u":"Молитва при заздрості до ближнього","e":"Prayer against Envy of One’s Neighbour","secs":[{"ps":["О Ти, Преблагий, Пресущедрий, Господи Ісусе Христе!","Усяке добро приходить від Тебе і через Тебе, зі скарбниці Твого вічного, непроминального багатства; Ти наділяєш кожного за волею Твоєю.","Не допусти мене через шкідливу заздрість зрівнятися з дияволом.","Влий у серце моє Твою доброту, Твою любов, Твою вірність, щоб я щиро радів дарам Твоїм, які Ти з щедрої доброти розподіляєш між нами, і Твоєму милосердю над нами; щоб ми не обтяжували одне одного заздрістю, брехнею, хулою й наклепом, але щоб ми все, Тобою нам дане, вживали на хвалу, честь і славу Твою, пізнавали Тебе в Твоїх благодіяннях і хвалили, шанували та прославляли по всі часи."]}],"notes":[]},{"u":"Молитва прп. Мойсею Мурину від пияцтва","e":"Prayer to St Moses the Black against Drunkenness","secs":[{"ps":["О преподобний, ти від тяжких гріхів досяг чудових чеснот, допоможи рабам Божим (імена), що моляться тобі, які вабляться до загибелі через те, що віддаються непомірному, шкідливому для душі й тіла вживанню вина. Схили на них свій милостивий погляд, не відхили й не погорди ними, але вислухай їх, що вдаються до тебе.","Молися, святий Мойсею, Владиці Христу, щоб не відкинув їх Він, Милосердний, і щоб не зрадів диявол їхній загибелі, але щоб пощадив Господь цих безсилих і нещасних, якими заволоділа згубна пристрасть п’янства, адже ми всі Божі створіння і викуплені Пречистою Кров’ю Сина Його.","Вислухай же, преподобний Мойсею, їхню молитву, віджени від них диявола, даруй їм силу подолати пристрасть, допоможи їм, простягни свою руку, виведи їх на шлях добра, визволи їх з рабства пристрастей і визволи від винопиття, щоб вони, оновлені, у тверезості й ясному розумі полюбили стриманість і благочестя та вічно прославляли Всеблагого Бога, Який завжди спасає створіння Свої. Амінь."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського при марнославних помислах","e":"Prayer of St John of Kronstadt against Vainglorious Thoughts","secs":[{"ps":["Господи, не дай мені вознестися в думках над собою як над кращим за будь-кого з людей, а думати про себе як про найгіршого з усіх і нікого не осуджувати, а себе судити суворо. Амінь."]}],"notes":[]},{"u":"Молитва в розпачі","e":"Prayer in Despair","secs":[{"ps":["Владико Господи неба й землі, Царю віків! Благоволи відчинити мені двері покаяння, бо я в болю серця мого молю Тебе, істинного Бога, Отця Господа нашого Ісуса Христа, Світла світові: зглянься в багатому милосерді Твоєму і прийми моління моє; не відверни його, але прости мені, що впав у численні провини. Бо шукаю спокою і не знаходжу, бо совість моя не прощає мені. Чекаю миру, а миру в мені нема через глибоку безліч беззаконь моїх. Вислухай, Господи, мене, що перебуваю в розпачі. Бо я, позбавлений усякої готовності й усякої думки про виправлення себе, припадаю до щедрот Твоїх: помилуй мене, повергненого на землю й засудженого за гріхи мої. Обрати, Господи, плач мій на радість мені, розірви веретище й підпережи мене веселістю. І благоволи, щоб я отримав спокій, як вибрані Твої, Господи, від яких відбігли хвороби, смуток і зітхання, і нехай відчиняться мені двері Царства Твого, щоб, увійшовши з тими, хто насолоджується світлом лиця Твого, Господи, одержати мені життя вічне у Христі Ісусі Господі нашому. Амінь."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського про мир у всьому світі","e":"Prayer of St John of Kronstadt for Peace in the Whole World","secs":[{"ps":["Слава Тобі, Богу, Благодійнику моєму, на віки віків! Будь пізнаний, Господи, у вірі Твоїй, усіма людьми Твоїми і всіма племенами земними, щоб усі прославили Тебе одними устами й одним серцем від сходу сонця до заходу. Буди, буди!"]}],"notes":[]},{"u":"Молитва перед посадкою дерев","e":"Prayer before Planting Trees","secs":[{"ps":["Господи Боже наш, що на початку сотворив небо і землю і небо прикрасив великими світилами для освітлення землі й величі, а землі даровав прикрасу із злаків і трави та різних насінь, що сіються кожне за родом своїм, і насадження квітучих дерев, і поблагословив їх! Сам і нині, Владико, зглянься зі святого житла Твого на сад цього володіння і на дерева, що насаджуються в ньому, і благословенням Твоїм поблагослови їх і збережи в повній цілості від усякого чарування, підступу, злого наміру лихих людей і від усякого зла, і дай йому, коли благополучно виросте, приносити вчасно плоди; віджени від нього силою благословення Твого всякого звіра, гада, черву, мух, попелицю, сарану, посуху, пекучі й несвоєчасні вітри, що завдають шкоди. Бо Ти один Бог милості й щедрот, і Тобі славослів’я приносимо, Отцю і Сину, і Святому Духу, нині і повсякчас, і навіки віків. Амінь."]}],"notes":[]},{"u":"Молитва до Бога при обході засіяного поля","e":"Prayer to God on Walking round a Sown Field","secs":[{"ps":["Всемогутній і вічний Боже, що створив з нічого світ, силою Своєю тримаєш його в просторі й повелів обробляти землю для існування роду людського! Ревно вдаємося до милосердя Твого: благослови милостивим оком Твоїм усе посіяне й насаджене на цих полях і городах (виноградниках) насіння; даруй спокій повітря й зроби насіння плодючим, збавивши його від заростання тернами й дикими травами, і дай йому повною силою дійти до призначеного часу, щоб ми, раби Твої, наситившись Твоїми зрілими плодами, могли завжди приносити Тобі достойне прославлення, нині і повсякчас, і навіки віків. Амінь."]}],"notes":[]},{"u":"Молитва до Ангела-Хоронителя перед іспитом","e":"Prayer to the Guardian Angel before an Exam","secs":[{"ps":["Святий ангеле Христів, вірний слуго Божий, воїне Його небесного воїнства, до тебе взиваю в молитві, осіняючи себе хрестом святим. Зішли мені небесну благодать на сили мої душевні й даруй мені розум і розуміння, щоб чуйно уважав я богоугодному навчанню, що його передає нам учитель, і розумом зріс надзвичайно на славу Господа, людям і святій Православній Церкві на користь. Про це прошу тебе, ангеле Христів. Амінь."]}],"notes":[]},{"u":"Молитва подяки св. Іоанна Кронштадтського","e":"Prayer of Thanksgiving by St John of Kronstadt","secs":[{"ps":["Дякую Тобі, Господи Боже мій, за дарування мені буття, за народження мене в християнській вірі, за Пречисту Діву Марію, Заступницю про спасіння роду нашого, за святих Угодників Твоїх, що моляться за нас, за Ангела Хоронителя, за спільне богослужіння, що підтримує в нас віру й чесноту, за Священне Писання, за Святі Таїнства, а особливо за Тіло і Кров Твою, за таємні благодатні втіхи, за надію отримати Царство Небесне і за всі блага, Тобою мені даровані."]}],"notes":[]},{"u":"Ранкова молитва св. Іоанна Кронштадтського","e":"Morning Prayer of St John of Kronstadt","secs":[{"ps":["Боже! Творче і Владико світу! Зглянься милостиво на створіння Твоє, прикрашене Твоїм божественним образом, у ці ранкові години: нехай оживить, нехай осяє Твоє Око, світліше за промені сонячні, мою душу темну й умертвлену гріхом. Віджени від мене зневіру та лінощі, даруй же мені веселість і бадьорість душевну, щоб у радості серця мого я славив Твою доброту, святість, Твою безмежну велич, безконечні Твої досконалості в кожну годину і на кожному місці. Бо Ти Творець мій і Владика життя мого, Господи, і Тобі належить слава від розумних створінь Твоїх у кожну годину, нині і повсякчас, і навіки віків. Амінь."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського про любов до ближніх","e":"Prayer of St John of Kronstadt for Love of Neighbour","secs":[{"ps":["Дай мені, Господи, любити кожного ближнього мого, як себе, завжди, і ні через що на нього не озлоблюватися й не служити дияволові.","Дай мені розп’яти моє себелюбство, гординю, користолюбство, маловірство й решту пристрастей.","Нехай буде в нас ім’я: взаємна любов; нехай віруємо й уповаємо, що для всіх нас усе — Господь; нехай не журимося й не тривожимося ні про що; нехай Ти, Боже наш, будеш єдиним Богом серця нашого, і, крім Тебе, нічого.","Нехай будемо ми між собою в єдності любові, як належить, і все, що розділяє нас одне від одного й відлучає від любові, нехай буде в нас у зневазі, як порох, топтаний ногами. Буди! Буди! Амінь."]}],"notes":[]},{"u":"Молитви подяки св. Іоанна Кронштадтського","e":"Prayers of Thanksgiving by St John of Kronstadt","secs":[{"ps":["Господи! Що я принесу Тобі, чим віддячу Тобі за Твої безперестанні, найбільші мені й людям Твоїм милості Твої? Бо ось я щомиті оживаю Духом Твоїм Святим, щомиті дихаю повітрям, Тобою розлитим, легким, приємним, здоровим, зміцнювальним, просвічуюся Твоїм радісним і животворним світлом, духовним і речовим; живлюся духовною їжею пресолодкою й животворною і таким же питтям — Святими Тайнами Тіла і Крові Твоєї, і їжею та напоями солодощів речових; Ти одягаєш мене пресвітлим, прекрасним, царським одягом — Собою Самим, за Писанням: хто у Христа христився, у Христа зодягнувся (Гал. 3:27), і одежами краси в храмі та поза ним речовими; очищаєш мої провини, зцілюєш і очищаєш пристрасті мої гріховні, численні й лютих, відіймаєш моє душевне тління в державі безмірної доброти, премудрості й міцності Твоєї; сповняєш Духом Твоїм Святим, Духом святині, благодаті, подаєш душі моїй правду, мир і радість, простір, силу, сміливість, мужність, міць; дорогоцінним здоров’ям і тіло моє обдаровуєш; навчаєш руки мої до війська і персти мої до бою (Пс. 143:1) з невидимими ворогами мого спасіння та блаженства і з ворогами святині й держави слави Твоєї — з духами злоби піднебесними; вінчаєш успіхами діла мої, що звершуються в імені Твоєму.","За все це дякую, славлю й благословляю всеблагу, отчу, всесильну державу Твою, Боже, Спасителю, Благодійнику наш. Але будь пізнаний так, як мені Ти пізнався, Чоловіколюбче, і рештою людей Твоїх, щоб знали Тебе, Отця всіх, Твою доброту, Твій промисел, Твою премудрість і силу і прославили Тебе з Отцем і Святим Духом нині і повсякчас, і навіки віків. Амінь."],"h":"Молитва подяки"},{"ps":["Дякую Тобі, Господи Боже мій, за дарування мені буття, за народження мене в християнській вірі, за Пречисту Діву Марію, Заступницю про спасіння роду нашого, за святих Угодників Твоїх, що моляться за нас, за Ангела Хоронителя, за спільне богослужіння, що підтримує в нас віру й чесноту, за Священне Писання, за Святі Таїнства, а особливо за Тіло і Кров Твою, за таємні благодатні втіхи, за надію отримати Царство Небесне і за всі блага, Тобою мені даровані."],"h":"Інша молитва подяки"},{"ps":["О Тройце, Боже наш, прості Єстество, що створило й душу нашу за образом Твоїм, щоб у Тобі мати життя й мир свій!","О Тройце, Годувальнице й Надіє наша! Дай нам у Тобі єдиній завжди покладати надію свою, у Тобі єдиній знаходити життя й спокій.","О Тройце! Ти, як мати, носиш усіх нас на руках Своїх і всіх нас годуєш із рук Своїх, як найніжніша мати! Ти ніколи не забуваєш і не забудеш нас; бо Ти Сам сказав: якщо й жінка забуде дитя своє — Я не забуду тебе (Іс. 49:15), тобто не перестану годувати, охороняти, захищати й спасати тебе."],"h":"Молитва до Пресвятої Тройці"}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського про того, хто не хоче ходити до храму","e":"Prayer of St John of Kronstadt for One Unwilling to Attend Church","secs":[{"ps":["Господи! Даруй, щоб храм Твій усім, хто входить до нього з вірою, благоговінням і страхом Божим, давав просвічення душ, очищення гріхів, освячення, мир, здоров’я, тишу душевну, — зміцнював віру, надію й любов, сприяв виправленню життя, успіхам у всіх добрих починаннях і ділах взаємної любові, чистому християнському життю, пом’якшенню сердець і припиненню себелюбства, жорстокосердя, користолюбства, жадібності, заздрості, злоби, ненажерства, п’янства, розпусти — цих вад, таких шкідливих у громадському житті та підриваючих його основи. Даруй це, даруй, Господи, всім, хто любить відвідувати храм Твій, і тих, хто його не любить, наверни до того, щоб любити його й виправляти серця та діла свої: бо час близько і суд при дверях для всіх людей усякого звання й стану, усякої статі й віку, і всім випадає справа безмежно великої ваги — дати відповідь на Страшному суді Христовому."]}],"notes":[]},{"u":"Молитва місіонера","e":"Missionary’s Prayer","secs":[{"ps":["Господи, Господи! Ти поклав Свою душу для спасіння всіх людей! Як Господар жнива Твого, пошли багато робітників на жнива Твої! Посланим же дай дух молитви, дух Твоєї любові, дух смирення, терпіння й розуму. Дай їм проповідувати з великою силою, щоб сповна виконати Твоє Євангеліє. Нехай зміцниться й зросте бажання тих, хто забажав допомагати нам ділами благодійної любові, нехай примножаться такі наші помічники. Віддай благодійникам нашим Твоїми благословеннями: живим подай здоров’я й благополуччя, спочилих зі святими Твоїми у вічних обителях упокой. Тих, хто ненавидить і кривдить нас, прости, Владико Чоловіколюбче, просвіти їхні серця, настав їхній розум. Усім же нам, викупленим Кров’ю Твоєю, тим, що знають Тебе й тим, що ще не знають, даруй світло розуму святого Твого Євангелія. Прискор покликати й з’єднати всіх в одне стадо Твоє тут, на землі, і перебувати з Тобою повіки нерозлучно у світлі Отця Твого й Бога нашого, Якому з Тобою і Святим Духом слава й могутність на віки віків. Амінь."]}],"notes":[]},{"u":"Молитва про дарування терпіння","e":"Prayer for Patience","secs":[{"ps":["Отче милосердя і Боже всякої втіхи! До Тебе взиваю я в ім’я Ісуса Христа про дарування мені істинного християнського терпіння. Озброй мене ним проти всякої скорботи, щоб я був у ній терплячим, бо це вельми дорогоцінне. Зроби мене готовим підняти на себе хрест Христів, терпляче нести його й твердо перебувати під ним до кінця. Віджени від мене всяке ремствування й усяку досаду плоті на тяжкість хреста й тривалість часу його. Стань, о улюблений Ісусе, зі Своїм терпінням під хрестом і на хресті, стань перед очима моїми й серцем моїм, щоб споглядаючи Тебе я підбадьорювався й зміцнювався до постійного перенесення всього. Зроби, о терплячий Спасителю, щоб я не втомлювався духом моїм, але в терпінні увійшов через страждання і скорботу в Царство Боже. Мені потрібно мати терпіння, щоб, виконавши волю Божу, отримати обіцяне. Я прошу його в Тебе, благоволи виконати прохання моє!"]}],"notes":[]},{"u":"Молитва того, хто подає милостиню","e":"Prayer of One Giving Alms","secs":[{"ps":["Господи! Навчи мене подавати милостиню охоче, з ласкою, з радістю, і вірити, що, подаючи її, я не втрачаю, а набуваю безконечно більше того, що подаю. Господи, нехай кожна моя милостиня піде на користь, а не на шкоду! Господи, прийми Сам милостиню в особі убогих Твоїх людей!"]}],"notes":[]},{"u":"Молитва при нечистих помислах","e":"Prayer against Impure Thoughts","secs":[{"ps":["Владико, Господи Боже мій, у руках Якого доля моя, спаси мене Сам за милістю Твоєю; не дай мені загинути в гріхах моїх і не допусти піти за нечистими бажаннями плоті, що оскверняють душу мою: бо я — Твоє створіння, не погордуй ділом рук Твоїх, не віддаляйся, змилосердься і не засоромлюй, не залиш мене, Господи, бо я немічний і до Тебе, Покровителя мого Бога, вдаюся, зціли душу мою, бо я згрішив перед Тобою. Спаси мене за милістю Твоєю, бо під Твоєю опікою був я від юності моєї, — нехай засоромляться ті, що хочуть віддалити мене від Тебе через діла гріховні, думки непристойні, спогади некорисні; віддали від мене всяку розпусту, надмір вад. Бо Ти один тільки Святий, один Міцний, один Безсмертний, у всьому незрівнянну могутність маєш і Тобою одним подається всім проти диявола і його війська сила. Бо належить Тобі всяка слава, честь і поклоніння, Отцю, і Сину, і Святому Духу, нині і повсякчас, і навіки віків. Амінь."]}],"notes":[]},{"u":"Молитва авви Дорофея від гніву","e":"Prayer of Abba Dorotheus against Anger","secs":[{"ps":["Боже милосердний і чоловіколюбний! Ти за невимовною Твоєю добротою створив нас з нічого для насолоди Твоїми благами і Кров’ю Єдинородного Сина Твого, Спасителя нашого, покликав нас, що відступили від Твоїх заповідей! Прийди і нині, допоможи нашій немочі, і як Ти колись заборонив бурхливому морю, так і нині заборони сум’яттю сердець наших, щоб Ти не втратив в одну годину нас обох, дітей Своїх, умертвлених гріхом, і щоб не сказав нам: «Яка користь у Крові Моїй, коли Я зійду в тління?» і: «Істинно кажу вам: не знаю вас», бо світильники наші погасли від браку єлею. Амінь."]}],"notes":[]},{"u":"Молитва при охолодженні любові до ближніх","e":"Prayer when Love for Others Grows Cold","secs":[{"ps":["Господи, що всюди всім даєш життя й подих і безперестанно через служіння створінь виявляєш любов Свою до всіх людей. Зроби в цьому й мене подібним до образу Твого, щоб і я невтомно, заради Тебе і за Твоїм прикладом, любив шляхетніше створіння Твоє — ближнього мого, і поводився з ним так, як того вимагає любов, через Ісуса Христа, Господа нашого. Амінь."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського від зневіри","e":"Prayer of St John of Kronstadt against Despondency","secs":[{"ps":["Господь — знищення зневіри моєї й оживлення сміливості моєї. Усе для мене Господь. О, воістину Сущий Владико, слава Тобі! Слава Тобі, Життя Отче, Життя Сину, Життя Душе Святий — Просте Єство — Боже, що завжди визволяєш нас від душевної смерті, яку пристрасті завдають душі нашій. Слава Тобі, Триіпостасний Владико, бо від одного призивання імені Твого просвітлюєш похмуре обличчя душі й тіла нашого і даруєш миром Твоїм, що перевершує всяке земне й чуттєве благо і всяке розуміння."]}],"notes":[]},{"u":"Молитви свт. Ігнатія (Брянчанінова)","e":"Prayers of St Ignatius (Brianchaninov)","secs":[{"ps":["Господи, Ти відвідуєш і приймаєш грішників! І воскрешаєш мертвих! І наказуєш водам моря, вітрам неба! І дивно ростуть хліби в руках Твоїх, дають тисячократний урожай, — сіються, жнуться, печуться й ламаються одночасно, в одну мить! І голодуєш Ти, щоб нас визволити від голоду! І прагнеш Ти, щоб угамувалася наша спрага! І мандруєш Ти країною нашого вигнання, утруджуючи Себе, щоб повернути нам втрачену нами, спокійну, сповнену небесних солодощів природу! Ти проливаєш піт Твій у саду Гетсиманському, щоб ми перестали проливати піт наш у здобуванні хліба, навчилися проливати його в молитвах для гідного причастя Хліба небесного. Терня, що його проклята земля вирощувала нам, Ти прийняв на голову Твою; Ти увінчав, поранив терням пресвяту голову Твою! Позбулися ми райського дерева життя та його плоду, що дарував безсмертя тим, хто його споживав, — Ти, розпростершись на дереві хресному, став для нас плодом, що дарує життя вічне причасникам Своїм. І плід життя, і дерево життя з’явилися на землі, у таборі нашого вигнання. Цей плід і це дерево переважають райські: ті дарували безсмертя, а ці дарують безсмертя й Божество. Твоїми стражданнями Ти вилив солодкість у наші страждання. Ми відкидаємо земні насолоди, обираємо в долю свою страждання, аби тільки стати причасниками Твоєї солодості! Вона, як передсмак життя вічного, солодша й дорожча за життя тимчасове! Ти заснув сном смертним, який не міг утримати Тебе у вічному засинанні, Тебе — Бога! Ти воскрес і даровав нам пробудження від цього сну, від лютого сну смертного, даровав блаженне й славне воскресіння! Ти вознісся оновленою природою нашою на небо, посадив її праворуч предвічного, Тобі співвічного, Отця Твого! Господи наш! Даруй нам і на землі, і на небі славословити, благословляти, вихваляти доброту Твою! Даруй нам відкритим лицем бачити страшну, неприступну, велелепну Славу Твою, вічно бачити Її, поклонятися Їй і блаженствувати в Ній. Амінь."],"h":"У сріблолюбстві й надії на земне"},{"ps":["Господи, даруй нам бачити гріхи наші, щоб розум наш, повністю спрямований на увагу до власних помилок наших, перестав бачити помилки ближніх і так побачив би всіх ближніх добрими. Даруй серцю нашому залишити згубну турботу про недоліки ближнього, усі турботи свої з’єднати в одну турботу про здобуття заповіданої й приготованої нам Тобою чистоти й святині. Даруй нам, що осквернили душевні ризи, знову вибілити їх: вони вже були омиті водами хрещення, потребують тепер, після осквернення, омивання слізними водами. Даруй нам побачити при світлі благодаті Твоєї різноманітні недуги, що живуть у нас, знищують у серці духовні рухи, вводять до нього рухи кровні й тілесні, ворожі Царству Божому. Даруй нам великий дар покаяння, якому передує і яке народжує великий дар бачення гріхів своїх. Збережи нас цими великими дарами від прірв самообману, який відкривається в душі від непомічуваної й нерозуміної нею гріховності її; народжується від дії непомічуваних і нерозумілих нею хтивості й марнославства. Охорони нас цими великими дарами на шляху нашому до Тебе і даруй нам досягти Тебе, що кличеш тих, хто визнає себе грішниками, і відкидаєш тих, хто вважає себе праведниками, щоб ми славословили вічно у вічному блаженстві Тебе, Єдиного Істинного Бога, Викупителя полонених, Спасителя загиблих. Амінь."],"h":"Про дарування покаянного почуття"},{"ps":["Дякую Тобі, Господи, Боже мій, за все, що звершилося наді мною! Дякую Тобі за всі скорботи й спокуси, які Ти послав мені для зцілення вражених гріхами моєї душі й тіла! Помилуй і спаси ті знаряддя, які Ти вживав для мого лікування, тих людей, які завдавали того, що вони творили для мене, призначи їм із вічних скарбів Твоїх щедрі нагороди. А що ж я приносив Тобі — самі гріхи, самі порушення Твоїх Божественних заповідей.","Прости мене, грішного, прости винного перед Тобою і перед людьми. Прости безвідповідного.","Даруй мені повірити й щиро визнати, що я грішник. Даруй мені відкинути лукаві виправдання, даруй мені покаяння, даруй мені розкаяння серця, даруй мені лагідність і смирення, даруй мені терпіння в усіх скорботах моїх. Умертви мене для світу. Відійми від мене мою гріховну волю й насади в серці моєму Твою святу волю. Нехай чиню її єдину і ділами, і словами, і думками, і почуттями моїми.","Тобі за все належить Слава, Тобі Єдиному належить Слава, моє єдине надбання — сором обличчя і мовчання уст.","Стоячи перед страшним судом Твоїм у бідній молитві моїй, не знаходжу в собі ні єдиного доброго діла, ні єдиної гідності і стою лише оповитий звідусіль незліченною безліччю гріхів моїх, як густою хмарою й імлою, з єдиною втіхою в душі моїй, з надією на безмежну милість і доброту Твою. Амінь."],"h":"Молитва того, кого переслідують люди"}],"notes":[]},{"u":"Молитва при немилосерді й роздратуванні на ближніх","e":"Prayer against Mercilessness and Irritation with Others","secs":[{"ps":["Милосердний, милостивий, благий, довготерпеливий, чуйний, добросердний Отче Небесний! Оплакую й визнаю перед Тобою вроджену лиху вдачу й черствість мого серця, що я часто немилосердям і недружелюбністю згрішив перед бідним ближнім моїм, не брав участі в його бідності й нещастях, що з ним траплялися, не мав до нього належного людського, християнського й братерського співчуття, залишав його в біді, не відвідував, не втішав, не допомагав йому. У цьому вчинив я не як дитя Боже, бо не був милосердним, як Ти,","Небесний мій Отче, і не думав про те, що каже Христос, Господь мій: блаженні милостиві, бо вони помилувані будуть. Не думав я про останній присуд на Страшному суді: ідіть від Мене, прокляті, у вогонь вічний; бо Я був голодний, і ви не дали Мені їсти; був нагий, і ви не зодягли Мене; був хворий, і не відвідали Мене.","Милосердний Отче! Прости мені цей тяжкий гріх і не залічи його мені. Відверни від мене тяжку й праведну кару, і зроби, щоб не здійснився наді мною суд без милості, але прикрий і забудь немилосердя моє заради милосердя улюбленого Сина Твого.","Даруй мені милосердне серце, яке б сумувало за лихом ближнього мого, і зроби, щоб швидко й легко спонукувався я до співчуття. Даруй мені благодать, щоб я сприяв полегшенню, а не збільшенню скорбот і лиха, що їх зазнає ближній мій; щоб я втішав його в смутку його і всім скорботним духом виявляв милосердя — хворим, мандрівникам, вдовам і сиротам; щоб допомагав їм охоче і любив не словом тільки, а ділом та істиною.","Боже мій! Милості хочеш Ти, а не жертви. Зроби, щоб я зодягнувся в серцеве милосердя, доброту, смирення, терпіння, і охоче прощав, як Христос простив мені. Зроби, щоб я пізнав велике милосердя Твоє до мене, бо я надто малий перед усім милосердям, яке Ти від дня народження мого виявляв наді мною. Милосердя Твоє випередило мене, коли я лежав у гріхах; воно огортає мене, воно йде за мною, куди б я не пішов, і зрештою прийме мене до себе в життя вічне. Амінь."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського від пияцтва","e":"Prayer of St John of Kronstadt against Drunkenness","secs":[{"ps":["Господи, милостиво поглянь на раба Твого (ім’я), якого обманула принада ненажерства й тілесних утіх. Дай йому пізнати, як солодка стриманість у пості і ті плоди Духа, що з неї випливають. Амінь."]}],"notes":[]},{"u":"Молитва до Господа нашого Ісуса Христа про дарування тверезості","e":"Prayer to Our Lord Jesus Christ for Sobriety","secs":[{"ps":["Ісусе Найсолодший! П’янство здолало мене! Душа моя знемоглася, настраждалася вся від нещасної слабкості моєї! Не дам собі ради — оце невтішна скорбота й біда моя. Побоювання й страх нападають на мене — аби не померти від п’янства без покаяння! Боюся, що ворог — диявол — остаточно погубить мене й доведе до пекла.","Знаю, що своїми силами мені не впоратися з собою. «Я ж бідний і вбогий, але Господь піклується про мене. Ти поміч моя й визволитель мій, Боже мій! Не забарися» (Пс. 39:18). Господи, Ісусе Христе! Ти Сам сказав: «Без Мене не можете робити нічого» (Ін. 15:5), але «просіть, і буде вам дане, шукайте, і знайдете, стукайте, і відчинять вам» (Мт. 7:7).","Ти, Господи Ісусе Христе, розслаблених зцілював, прокажених очищав, блудницю помилував, розбійникові сказав: «Сьогодні будеш зі Мною в раю» (Лк. 23:43). Торкнися ж, Милосердний, і мого розслабленого й блудного серця Своєю всесильною благодаттю, влий у нього силу й бадьорість духа на боротьбу з пристрастю п’янства, прожени диявола-спокусника й пошли мені Ангела Твого Хоронителя, і «якими знаєш путями» спаси мене, грішного й зневіреного, Господи!","Ти Сам сказав: «Не хочу смерті грішника, а щоб грішник навернувся від дороги своєї і жив» (Єз. 33:11), і тому «прийшов у світ спасти грішників» (1 Тим. 1:15). Ти Сам Своїми Божественними устами промовив: «Того, хто приходить до Мене, не відкину» (Ін. 6:37). І ось я прийшов до Тебе, надіє моя й пристановище! Плачу біля Пречистих ніг Твоїх, Розіп’ятий за мене.","«Не сховай від мене лиця Твого, не відкинь мене і не залиш мене, Боже, Спасителю мій!» (Пс. 26:9), даруй мені силу й міцність волі, щоб я вигнав геть пристрасть, що гніздиться в мені, і щоб жив у тверезості, благочесті й твердій вірі в Тебе, Єдиного Істинного Бога Отця, Сина і Святого Духа. Амінь."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського, коли помітиш за собою гріх","e":"Prayer of St John of Kronstadt on Noticing One’s Sin","secs":[{"ps":["Господи! Ти, що пригвоздив наші гріхи до хреста, пригвозди до хреста Твого й теперішній мій гріх і помилуй мене за великою Твоєю милістю."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського при розділеннях і ворожнечі між віруючими","e":"Prayer of St John of Kronstadt in Divisions and Enmity among Believers","secs":[{"ps":["Господи! Навчи нас жити у взаємній любові й зміцни нас Твоїм Святим Духом; угамуй поривання пристрастей, що перешкоджають небесній, євангельській любові, і зроби наші серця мертвими для земних насолод.","Дай мені, Господи, завжди віддавати перевагу над усіма земними благами Твоїй благодаті, Твоєму миру, правді й святості Твоїм і перебувати в них у всі дні життя, до останнього подиху!","Дай мені, Господи, любити кожного ближнього мого, як самого себе, завжди, ні через що на нього не гніватися й не працювати на диявола.","Дай мені розіп’ясти моє себелюбство, гординю, сріблолюбство, маловір’я й решту пристрастей. Нехай нашим іменем буде: взаємна любов; нехай віруємо й уповаємо, що для всіх нас усе — Господь; нехай не журимося, не тривожимося ні про що, щоб Ти, Боже наш, був єдиним Богом нашого серця, і крім Тебе — ніщо інше.","Нехай будемо ми між собою в єдності любові, як і належить, і все, що розділяє нас одне від одного й відлучає від любові, нехай буде в нас у зневазі, як порох, топтаний ногами. Хай буде так! Хай буде так!"]}],"notes":[]},{"u":"Інша молитва з творінь прп. Єфрема Сиріна (при зневагах від ближніх)","e":"Another Prayer from the Works of St Ephrem the Syrian (in Insults from Others)","secs":[{"ps":["Помилуй, Господи, тих, що ненавидять мене й заздрять мені! Помилуй, Господи, тих, що обмовляють мене й завдають мені образ! Нічого лихого не твори з ними за недостойного раба Твого; але за невимовним милосердям Твоїм і за безмірною добротою Твоєю ні в цьому житті, ні в віці майбутньому нехай не зазнають вони зла через мене, грішного! Освяти їх милістю Твоєю й осіни благодаттю Твоєю, Всеблагий, бо перед усіма благословенний Ти повіки віків. Амінь."]}],"notes":[]},{"u":"Молитви прп. Силуана Афонського","e":"Prayers of St Silouan the Athonite","secs":[{"ps":["Господи, дай мені смиренного духа Твого, щоб не втратив я Твою благодать і не став би ридати за нею, як ридав Адам за раєм і Богом. Господи, Ти Милостивий; скажи мені, що я маю робити, щоб упокорилася душа моя? Господи, удостой нас дару Твого святого смирення. Господи, даруй нам лагідність смиренного Духа Твого Святого, як з лагідністю прийшов Ти спасти людей і вознести їх на небо, щоб вони бачили славу Твою. Пресвята Мати Господа, випроси, Милостива, нам смиренного духа. Усі Святі, ви живете на небесах і бачите славу Господню, і радіє дух ваш, — моліться, щоб і нам бути з вами."],"h":"Прохання про смирення"},{"ps":["Господи, даруй мир Твій людям Твоїм. Господи, даруй рабам Твоїм Духа Твого Святого, щоб Він зігрівав серця їхні любов’ю Твоєю й наставляв їх на всяку істину й добро. Господи, даруй їм благодать Твою, щоб вони в мирі й любові пізнали Тебе, і полюбили б, і сказали б, подібно до апостолів на Фаворі: «Добре нам, Господи, бути з Тобою». Зігрій сумні серця людей; нехай вони в радості славлять Тебе, забуваючи скорботи землі. Утішителю благий, зі сльозами прошу Тебе, утіш скорботні душі людей Твоїх. Дай усім народам Твоїм зрозуміти любов Твою й солодкість Духа Святого, щоб забули люди горе землі, і залишили все погане, і прилинули до Тебе любов’ю, і жили в мирі, виконуючи волю Твою на славу Твою."],"h":"Молитва про мир"},{"ps":["Пресвята Мати Господа, випроси, Милостива, нам смиренного духа. Усі святі, ви живете на небесах і бачите славу Господню, і радіє дух ваш, — моліться, щоб і нам бути з вами. Тягнеться й моя душа бачити Господа і тужить за Ним у смиренні, як недостойна цього блага. Господи Милостивий, Духом Святим навчи нас смирення Твого.","Господи, виправ нас, як ніжна мати виправляє своїх малих дітей.","Дай кожній душі пізнати радість Пришестя Твого й силу допомоги Твоєї. Дай прохолоду стражденним душам народу Твого, і всіх нас навчи Духом Святим знати Тебе. Томиться душа людська на землі, Господи, і розумом не може зміцнитися в Тобі, бо не знає Тебе й Твоєї доброти."],"h":"До Пресвятої Матері Господа"},{"ps":["О Господи, навчи нас Духом Твоїм Святим бути слухняними, стриманими. Дай нам дух Адамового покаяння й сльози за гріхи наші. Дай нам вічно славити Тебе й дякувати. Ти дав нам пречисте тіло Твоє й кров, щоб ми вічно жили з Тобою, і були там, де Ти перебуваєш, і бачили славу Твою."],"h":"Про послух і покаяння"},{"ps":["Господи, дай народам усієї землі пізнати, як багато Ти нас любиш і яке дивне життя Ти даєш тим, що вірують у Тебе.","Помилуй мене, Боже, занепале створіння Твоє.","Скільки разів Ти давав мені благодать Свою, а я не зберіг її, бо марнославна душа моя; але душа моя знає Тебе, Творця й Бога мого, і тому шукаю Тебе, ридаючи, як ридав Йосиф за батьком своїм Яковом на гробі матері своєї, ведений у єгипетське рабство.","Я ображаю Тебе гріхами, і Ти відходиш від мене, і душа моя тужить за Тобою.","О Душе Святий, — не залиш мене. Коли Ти відходиш від мене, то погані думки приходять до мене, і тужить душа моя за Тобою до великих сліз."],"h":"Про пізнання Божої любові"},{"ps":["Господи, дай мені Тебе єдиного любити.","Ти створив мене, Ти просвітив мене святим хрещенням, Ти прощаєш мені гріхи й даєш причащатися Пречистого Тіла Твого і Крові; дай же мені силу завжди перебувати в Тобі.","Господи, дай нам Адамове покаяння й Твоє святе смирення.","Дай, Господи, всім народам Твоїм зрозуміти любов Твою й солодкість Духа Святого, щоб забули люди горе землі, і залишили все погане, і прилинули до Тебе любов’ю, і жили в мирі, виконуючи волю Твою на славу Твою.","О Господи, удостой нас дару Духа Святого, щоб ми розуміли славу Твою і жили на землі в мирі й любові, щоб не було ні злоби, ні воєн, ні ворогів, але одна любов нехай царює, і не потрібні будуть ні армії, ні в’язниці, і легко жити буде всім на землі.","Господи, як Сам Ти молився за ворогів, так і нас Духом Твоїм Святим навчи любити ворогів.","Господи, усі народи — створіння рук Твоїх, наверни їх від ворожнечі й злоби до покаяння, щоб усі пізнали любов Твою.","Господи, Ти заповів любити ворогів, але важко нам, грішним, якщо з нами нема Твоєї благодаті.","Господи, вилий на землю Твою благодать; дай усім народам землі пізнати Твою любов, пізнати, що Ти любиш нас, як мати, і більше за матір, бо й мати може забути плід свого лона, а Ти ніколи не забуваєш, бо Ти безмірно любиш створіння Своє, а любов не може забути.","Господи Милостивий, багатством милості Твоєї спаси всі народи."],"h":"Про любов до Бога"}],"notes":[]},{"u":"Молитва свт. Миколая Сербського про мир у всьому світі","e":"Prayer of St Nikolaj of Žiča for Peace in the Whole World","secs":[{"ps":["Господи Боже наш, Владико життя і смерті, Творче неба й землі, прийми нашу подяку за всі добрі дари, які Ти подав нам у цей час. Ти дарував нам і безперестанку даруєш те, чого ніхто інший не міг би дати: здоров’я, достаток земних плодів і все інше, що потрібне для нашого існування на землі. Духом же Твоїм Святим надихаєш Ти й утверджуєш правдиву віру, осяваєш надію, розпалюєш любов, милуєш милістю, просвічуєш і освячуєш душі народу Твого. Дякуємо Тобі за те, що багатством Своєї милості переважив Ти згубне багатство людських гріхів, так що — дивлячись на наші провини — ще не замкнув небес над нами, і не висушив хмар від дощу, і не заборонив землі родити плоди, і не наказав сонцю більше не осявати грішників і беззаконників.","Але, о Всеблагий Царю і Господи, один Твій невідкладний дар бракує нам у цей час — мир, той святий мир, який Ти даровав Своїм великим Апостолам, кажучи: Мир вам!… Мир залишаю вам, мир Мій даю вам! Про цей мир, про цей небесний дар, який у Твоїй руці й тільки від Тебе може прийти, ми навколішки Тебе молимо. Знаємо, Творче наш, знаємо, що не заслужили ми його і недостойні цього дару, проте покладаємо надію на Твоє безмежне милосердя і покаянно молимося Тобі єдиному: «Даруй нам його, даруй мир усім вірним Твоїм по всьому світу, щоб ми не загинули до кінця». Господи, схвилювалося нині й закипіло море людського життя, як ніколи. Запанувало сум’яття разом із жахом у серцях людей. Озброївся і повстав брат на брата, сусід на сусіда, народ на народ, царство на царство.","І ось рід людський стоїть на порозі нової війни, нового Каїнового гріха, нової Іудиної зради, — тієї війни, в якій будуть потоптані всі Твої заповіді, Твоє святе ім’я зазнає хули, Твоя жертва буде осміяна, а Твоя свята любов до нас, грішних, стане предметом зневаги. О всемогутній Вседержителю, простягни Свою непереможну правицю і не допусти цього, не дозволь цього, відверни це Своєю силою й добротою. Як колись угамував Ти Галілейське море і Своїм всемогутнім словом вгамував вітри, вселивши мир і радість у душі Своїх учнів, так і нині втихомир бурю в душах Своїх людей і народів, щоб замість страху перед війною засяяла в них втіха миру. Збережи, Господи, вибраних Своїх від осоромлення перед язичниками. Охорони Своїх охрещених людей і Свої народи від глузувань сатани над створіннями Твоїми. Змилуйся принаймні над Своїми святими Ангелами і не допусти їм знову в скорботі дивитися на безбожні діла християнських народів. Змилуйся над Своїми святими й праведниками і не попусти, щоб знову перед Твоїм небесним престолом опускали вони очі, соромлячись своїх родичів і нащадків тут, на грішній землі.","Тому заради Своїх Ангелів і святих і праведників на небесах — більше, ніж заради нас, — помилуй нас, Многомилостивий. І заради любові Пресвятої Твоєї Матері, Богородиці, до Тебе, Господи Ісусе Христе, і до Церкви Твоєї на землі, Твого виноградника й насадження, утримай наші руки від злочинів і спаси нас від нас самих. Спаси нашу совість, спаси наші душі, щоб і ми, визволені Твоєю милістю, примножили у слушний час святий Твій народ у безсмертному Царстві миру, світла й життя, де з вічності у вічність живеш і царюєш Ти, Триєдиний Боже наш, Тобі ж нехай буде слава й хвала, подяка й поклоніння від усіх святих Сил на небі, від усіх родів на землі, на віки віків. Амінь."]}],"notes":[]},{"u":"Молитва до Бога про громадянський мир","e":"Prayer to God for Public Peace","secs":[{"ps":["Милосердний, милостивий і благий Боже миру! Ми пізнаємо й визнаємо, яке велике благо і дорогоцінний скарб є улюблений мир, без якого не може бути жодного благословення й успіху в якійсь землі, а буває єдина загибель, прокляття й лихо. Просимо ми Тебе від усього серця: благоволи милістю Твоєю та могутністю Твоєю зберегти владик від ворожнечі та війни, а володіння їхні від руйнування й спустошення, благоволи даровати й зіслати всім високим владикам мирне налаштування душі, миролюбні поради й порадників, що творять мир і понад усе люблять істину й мир. Даруй нам послух слову Твоєму й владам, над нами поставленим, щоб ми самі не проганяли від себе дорогоцінного миру. Улюблений Отче! Зроби, щоб ми перебували в мирі, бо Ти не Бог незгоди, а Бог миру. Даруй нам мати мир між собою, щоб Ти, о Боже миру й любові, перебував з нами. Амінь."]}],"notes":[]},{"u":"Молитва при безробітті","e":"Prayer in Unemployment","secs":[{"ps":["Господи Ісусе Христе, Сину Божий, Пресвята Богородице і святий мучениче Трифоне, пошліть мені добру й чесну працю на славу Божу і на користь ближніх моїх."]}],"notes":[]},{"u":"Молитва до Господа на благословення дому","e":"Prayer to the Lord for the Blessing of a House","secs":[{"ps":["Нехай благословить нас і збереже Всемогутній Милосердний Бог Отець, Бог Син, Бог Дух Святий.","О найсолодший Ісусе Христе, Всемогутній Царю неба й землі, Сину Давидів, Ісусе Назарянине, за нас розіп’ятий на Хресті, змилуйся над цим домом, храни тих, що живуть у ньому. Нехай Твоє Господнє благословення супроводжує їх усюди; нехай Дух Святий освятить думки й серця їхні; Його всемогутність усюди, на кожному місці: усе, що є в цьому домі, хто до них входить і хто від них виходить, нехай благословить Пресвята Тройця і збереже від усякого зла, щоб ніщо нечисте не наблизилося до них.","Ім’я Господа Ісуса Христа з дев’ятьма чинами Ангелів нехай буде в цьому домі й дасть йому свій спокій. Нехай покриє своїм материнським Покровом Пресвята Діва Марія, нехай охороняють його святі Апостоли, добробут його нехай утвердять і зміцнять святі Євангелисти.","Хрест Господа нашого Ісуса Христа нехай буде йому дахом; цвяхи Господа нашого Ісуса Христа нехай будуть його захистом; вінець Господа нашого Ісуса Христа нехай буде його покровом.","Пресвята Діво Маріє, святий праведний Йосифе і всі святі, Ангели Хоронителі, умоліть Господа нашого Ісуса Христа, Єдиного з Пресвятої Тройці, щоб зберіг цей дім від грому, блискавки, вогню, граду, повені, від нападу лихих людей, нужди, невір’я, єресі, війни і всякого нещастя, що загрожує душі й тілу, у чому нехай допоможе нам Бог Отець, Бог Син, Бог Дух Святий. Амінь.","Удостой, Господи, у день цей (або: ніч цю) без гріха зберегтися нам.","Господи, помилуй, Господи, помилуй, Господи, помилуй."]}],"notes":[]},{"u":"Молитва до Бога про збереження посівів і садів","e":"Prayer to God for the Preservation of Crops and Orchards","secs":[{"ps":["Тебе, Владико, молимо: вислухай моління наше, щоб за милістю Твоєю, заради слави імені Твого, були визволені посіви й сади наші, нині справедливо за гріхи наші знищувані й нинішнє лихо терплячі, від птахів, червів, мишей, кротів та інших тварин, і нехай вони, вигнані далеко з цього місця Твоєю владою, нікому не шкодять, а поля ці, і води, і сади залишать у цілковитому спокої, щоб усе, що в них росте й родиться, служило на славу Твою і допомагало нашим потребам, бо Тебе славлять усі Ангели, і ми Тобі славу приносимо, Отцю і Сину і Святому Духу, нині і повсякчас, і навіки віків. Амінь."]}],"notes":[]},{"u":"Молитви православного воїна","e":"Prayers of an Orthodox Soldier","secs":[{"ps":["Пресвята моя Владичице Богородице, Твоїми святими й всесильними молитвами віджени від мене, недостойного й нещасного раба Твого, зневіру, забудькуватість, нерозважливість, недбальство і всі скверні, лихі й безбожні думки з мого нечистого серця й від мого затьмареного розуму; погаси полум’я моїх пристрастей, бо я безсилий на добрі діла, і визволи мене від усяких скверних спогадів і лихих задумів, і звільни мене від усіх лихих діл, бо Тебе благословляють усі народи і Твоє найчесніше ім’я прославляється на віки віків. Амінь."],"h":"До Пресвятої Богородиці"},{"ps":["Ангеле Божий, хоронителю мій святий, даний мені з неба від Бога для охорони (мене), щиро прошу тебе: ти сьогодні (навчи й) просвіти мене, збережи від усякого зла, настав на добрі діла й спрямуй на шлях спасіння. Амінь."],"h":"До святого Ангела-хоронителя"},{"ps":["Спасителю мій! Ти поклав за нас душу Свою, щоб спасти нас; Ти заповів і нам покладати душі свої за друзів наших, за близьких нам. Радісно йду я виконувати святу волю Твою й покласти життя своє за народ мій і Вітчизну. Озброй мене міцністю й мужністю на подолання ворогів наших і даруй мені померти з твердою вірою і надією вічного блаженного життя в Твоєму Царстві.","Мати Божа! Збережи мене під покровом Твоїм. Амінь."],"h":"Молитва перед боєм"}],"notes":[]},{"u":"Молитва свт. Гавриїла Новгородського про навернення того, хто збився з путі","e":"Prayer of St Gabriel of Novgorod for the Conversion of One Gone Astray","secs":[{"ps":["О Всемилостива Госпоже, Діво Владичице Богородице, Царице Небесна! Ти Своїм різдвом спасла рід людський від вічного мучительства диявола: бо від Тебе народився Христос, Спаситель наш. Зглянься Своїм милосердям і на цього (ім’я), позбавленого милості Божої й благодаті, випроси Материнською Своєю сміливістю і Твоїми молитвами в Сина Твого, Христа Бога нашого, щоб зіслав благодать Свою з висоти на цього, що гине. О Преблагословенна! Ти надія безнадійних, Ти розпачливих спасіння, нехай не зрадіє ворог за душу його!"]}],"notes":[]},{"u":"Молитва старця Євстратія Глинського про лагідність і смиренномудрість","e":"Prayer of Elder Eustratius of Glinsk for Meekness and Humility","secs":[{"ps":["Господи, дай мені дух лагідності, щоб бути лагідним до ближніх моїх і стриманим у гніві.","Даруй мені дух смиренномудрості, щоб не думати про себе високо і не гордитися."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського про допомогу Божу в боротьбі з ворогами","e":"Prayer of St John of Kronstadt for God’s Help against Enemies","secs":[{"ps":["Господи, Ти Суддя землі, Ти не любиш неправди, вислухай молитву мою недостойну і пошли силу Твою, і пошли допомогу Твою там, де зустрінуть мене вороги видимі й невидимі, і щоб стали стовпи на тому місці, де їх зустріне сила Твоя. Амінь."]}],"notes":[]},{"u":"Молитва прп. Нектарія Оптинського","e":"Prayer of St Nectarius of Optina","secs":[{"ps":["Господи, даруй мені благодать Твою, — так навчав молитися преподобний старець Нектарій і казав: «Ось іде на вас хмара, а ви моліться: Дай мені благодать, — і Господь пронесе хмару повз»."]}],"notes":[]},{"u":"Молитва св. Іоанна Кронштадтського «Я — чудо Твоєї благості»","e":"Prayer of St John of Kronstadt “I am a miracle of Thy goodness”","secs":[{"ps":["Господи! Я — чудо Твоєї доброти, премудрості, всемогутності, оскільки приведений Тобою з небуття в буття, оскільки зберігаюся Тобою досі в бутті, оскільки маю, за добротою, щедротами й чоловіколюбством єдинородного Сина Твого, успадкувати життя вічне, якщо вірним Тобі залишуся, оскільки страшним священнодійством принесення Себе Самого в жертву Сином Твоїм я піднятий з жахливого падіння, викуплений від вічної загибелі. Славлю Твою доброту, Твою безконечну могутність, Твою премудрість! Але яви чудеса Твоєї доброти, всемогутності й премудрості наді мною, окаянним, і якими знаєш путями спаси мене, недостойного раба Твого, і введи в Царство Твоє вічне, удостой мене життя нестаріючого, дня незаходимого."]}],"notes":[]},{"u":"Щоденна молитва ієросхимонаха Парфенія Київського","e":"Daily Prayer of Hieroschemamonk Parthenius of Kyiv","secs":[{"ps":["Господи, Ісусе Христе, Сину Божий, не допусти, щоб марнота, себелюбство, чуттєвість, недбальство, гнів панували наді мною й викрадали мене в любові Твоєї. О Господи, Створителю мій, уся Надіє моя! Не залиш мене без уділу в блаженній вічності; зроби, щоб і я наслідував святий приклад Твій. Даруй мені цю чистоту духа, цю простоту серця, які роблять нас достойними любові Твоєї. До Тебе, о Боже мій, підношу душу й серце моє, не допусти загинути створінню Твоєму, але визволи мене від найбільшого й єдиного справжнього зла — гріха. Зроби, Господи, щоб я переносив з таким самим терпінням душевні тривоги й скорботи, з якою радістю приймаю серцеві втіхи. Якщо Ти хочеш, Господи, — можеш очистити й освятити мене. Ось я віддаю себе Твоїй доброті, прохаючи вигубити з мене все противне Тобі й приєднати до сонму вибраних Твоїх. Господи! Відійми від мене бездіяльність духа, що марнує час; марноту думок, що заважають Твоїй присутності й розсіюють мою увагу в молитві; якщо ж, молячись, я ухиляюся від Тебе моїми помислами, то допоможи мені, щоб, відвертаючи розум, я не відвертав серця від Тебе. Сповідаю Тобі, Господу Богу моєму, всі гріхи беззаконня мого, нині й раніше вчинені перед Тобою: відпусти мені їх заради імені Твого святого і спаси душу мою, яку Ти викупив дорогоцінною Кров’ю Твоєю. Вручаю себе милосердю Твоєму, віддаюся на волю Твою, твори зі мною за добротою Твоєю, а не за злобою й беззаконням моїм. Навчи мене, Господи, влаштовувати справи свої так, щоб вони сприяли прославленню імені Твого святого. Змилуйся, Господи, над усіма християнами, вислухай бажання всіх, хто взиває до Тебе, визволи від усякого зла й спаси рабів Твоїх (імена): пошли їм розраду, втіху в скорботах і милість Твою святу. Господи! Молю Тебе особливо за тих, що мене чимось скривдили й засмутили, або якесь зло заподіяли: не карай їх заради мене, грішного, але пролий на них доброту Твою. Господи! Молю Тебе за всіх, кого я, грішний, засмутив, скривдив або спокусив словом, ділом, думкою, відомо чи несвідомо. Господи Боже! Відпусти нам гріхи наші та взаємні образи; віддали, Господи, з сердець наших усяке обурення, підозру, гнів, злопам’ятність, сварки й усе, що може перешкоджати любові й зменшувати братолюбство. Помилуй, Господи, тих, що доручили мені, грішному й недостойному, молитися за них! Помилуй, Господи, кожного, хто просить Твоєї допомоги. Господи! Зроби цей день днем милосердя Твого, подай кожному за проханням його; будь пастирем тих, що заблукали, проводирем і світлом невідаючих, наставником немудрих, батьком сиріт, помічником утиснених, лікарем хворих, утішителем умираючих, і приведи нас усіх до бажаної мети — до Тебе, Пристановища нашого й блаженного упокою. Амінь."]}],"notes":[]},{"u":"Щоденна молитва святителя Філарета (Дроздова)","e":"Daily Prayer of St Philaret (Drozdov)","secs":[{"ps":["Господи, я не знаю, чого мені просити в Тебе. Ти один знаєш, що мені потрібно. Ти любиш мене більше, ніж я вмію любити себе.","Отче, дай рабу Твоєму те, про що я сам не вмію просити. Не смію просити ні хреста, ні втіхи: тільки стою перед Тобою. Серце моє відкрите для Тебе; Ти бачиш потреби, яких я не знаю. Поглянь і твори за милістю Твоєю. Вразь і зціли, скинь і підійми мене. Благоговію й мовчу перед Твоєю святою волею й непостижними для мене Твоїми законами.","Приношу себе в жертву Тобі. Нема в мене іншого бажання, крім бажання виконувати волю Твою. Навчи мене молитися. Сам у мені молись! Амінь."]}],"notes":[]},{"u":"Пісня хвалебна за подобою псалмів Давидових (св. Іоанн Кронштадтський)","e":"Hymn of Praise after the Manner of David’s Psalms (St John of Kronstadt)","secs":[{"ps":["Господь — буття моє, Господь — визволення від вічної смерті, Господь — вічне життя моє, Господь — очищення й визволення від безлічі провин і освячення моє, Господь — сила в немочі моїй, простір у тісноті моїй, надія в малодушші й зневірі моїй. Господь — животворний вогонь у холоді моєму, Господь — світло в темряві моїй, мир у сум’яття моєму, Господь — захисник у спокусах моїх. Він — мислення моє, бажання моє, діяльність моя, Він — світло душі й тіла, їжа, питво, одяг мій, щит мій, зброя моя. Усе для мене Господь. Душе моя, люби й дякуй безперестанку Господеві!"]}],"notes":[]},{"u":"Молитви й богомислення свт. Тихона Задонського на всяку потребу","e":"Prayers and Meditations of St Tikhon of Zadonsk for Every Need","secs":[{"ps":["Слава Богу за все!","Слава Богу, що мене створив за образом Своїм і за подобою!","Слава Богу, що мене, занепалого, викупив!","Слава Богу, що про мене, недостойного, промишляв!","Слава Богу, що мене, грішного, на покаяння покликав!","Слава Богу, що мені дав слово Своє святе, як «світильник, що світить у темному місці» (2 Пет. 1:19), і тим мене на шлях істинний настановив!","Слава Богу, що мої очі серцеві просвітив!","Слава Богу, що дав мені в пізнання святе ім’я Своє!","Слава Богу, що купіллю Хрещення гріхи мої омив!","Слава Богу, що показав мені шлях до вічного блаженства! А шлях — Ісус Христос, Син Божий, Який про Себе каже: «Я є шлях, і істина, і життя» (Ін. 14:6).","Слава Богу, що грішного мене не погубив, а за Своєю добротою потерпів гріхи мої!","Слава Богу, що показав мені облуду й марноту світу цього!","Слава Богу, що допомагав мені в різноманітних спокусах, бідах і напастях!","Слава Богу, що при бідах і смертельних випадках мене зберігав!","Слава Богу, що мене від ворога, диявола, захищав!","Слава Богу, що мене, лежачого, піднімав!","Слава Богу, що мене, сумного, втішав!","Слава Богу, що мене, блукаючого, навертав!","Слава Богу, що мене по-батьківськи карав!","Слава Богу, що мені об’явив Страшний Свій Суд, щоб я його боявся й каявся в гріхах моїх!","Слава Богу, що об’явив мені вічну муку й вічне блаженство, щоб однієї уникнути, а другого шукати!","Слава Богу, що мені, недостойному, подавав їжу, якою зміцнювалося немічне моє тіло; подавав одяг, яким покривалося наге моє тіло, подавав дім, у якому я спочивав!","Слава Богу й за решту Його благ, які Він мені на утримання й втіху моє подавав! Стільки я від Нього отримав благодіянь, скільки подихів зробив!","Слава Богу за все!"],"h":"Молитва-подяка із духовного заповіту"},{"ps":["«Господи, не гнівом Твоїм докоряй мені, ні люттю Твоєю карай мене» (Пс. 6:2). Подібно до цього молиться пророк Єремія: «Карай нас, Господи, але по суду, а не в гніві, щоб не применшив нас» (Єр. 10:24). І інше Псалмоспівця: «Не входь у суд з рабом Твоїм, бо не виправдається перед Тобою ніхто з живих» (142:2). І ще: «Якщо Ти беззаконня запримітиш, Господи, Господи, хто встоїть?» (Пс. 129:3). Не просто від кари Божої слід просити визволення, а від гніву й суворості правди Божої, яка кожному грішнику загрожує вічною мукою. А батьківської кари Божої, хоч вона й гірка для нашої плоті, слід бажати, адже «Господь, кого любить, того карає; б’є ж кожного сина, якого приймає» (Євр. 12:6). І Сам Христос каже: «Кого Я люблю, тих докоряю й караю» (Одкр. 3:19). Горе ж кожній людині, коли Бог з нею за суворістю правди Своєї у суд увійде! Нічого іншого, окрім вічної муки в огні геєнському, не доведеться їй чекати. Бо кожен гріх, навіть найменший, на нашу думку, здатний занурити людину на дно пекла, якщо не прийде милість Божа, заради Сина Його, Ісуса Христа, обіцяна. Що ж казати про тих, що згрішають добровільно? Тому належить кожному, хто хоче суду Божого уникнути, від гріхів відстати і молити Бога з вірою у Христа: «Господи, не гнівом Твоїм докоряй мені», і так далі."],"h":"3. Молитва того, хто відчуває в совісті гнів Божий"},{"ps":["«Господи, чому намножилися ті, що гнітять мене? Багато повстає на мене; багато кажуть душі моїй: нема спасіння їй у Бозі її. Ти ж, Господи, Заступник мій, слава моя, і Той, що підіймає голову мою» (Пс. 3:2–4). Вірному, а особливо такому, що перебував у гріхах і благодаттю Божою від них відстав і кається, сатана часто вкладає злі помисли, нагадуючи йому колишні гріхи, і ними совість його гнітить, кажучи: «Перестань вірити, будеш засуджений. Стільки й стільки ти згрішив, Бога Праведного, Який усім віддає за ділами, розгнівав. На що тобі сподіватися, окрім однієї муки?» (Прп. Макарій Єгипетський, Бесіда 11). І так злий і підступний дух хоче привести каянника до розпачу. У такому разі можна злому духові відповідати: «Ти наклепник, і вже засуджений, а не суддя; суд же даний Христові, Який прийшов у світ спасти грішників, у Якого і я вірую, і сподіваюся Його благодаттю спастися». І слід звернутися до молитви й утвердити себе Божим милосердям, яке жоден гріх подолати не може. Скільки б гріхів не було в кого, і які б великі не були, — у Бога милосердя ще більше. Бо як Сам безконечний, так і милість Його безконечна. І заслуги Христові, якими Він нам, що віруємо в Нього, заслужив милість, благодать і відпущення гріхів у Отця Небесного, так само безконечні, як і Божественні. Цим чоловіколюбством Божим утішай себе, душе, що каєшся, і благодаттю Божою та молитвою стій у вірі. Лише тим неодмінно випадає в пеклі з дияволом вічний осуд, які не хочуть каятися й від гріхів відстати. А тим, що відстали від гріхів і каються, відчинені двері милосердя Божого."],"h":"5. Молитва, коли помисли бентежать душу й схиляють до зневіри в Божій милості"},{"ps":["«Господи Вседержителю, Боже Ізраїлів! Душа в тісноті і дух у стражданні взивають до Тебе: вислухай, Господи, і помилуй, бо Ти Бог милосердний, і помилуй нас, бо ми згрішили перед Тобою» (Вар. 3:1–2). Подібно до цього Псалмоспівець: «Ти захисток мій від скорботи, що обступила мене. Радосте моя! Визволи мене від тих, що оточили мене» (Пс. 31:7). Від кожної скорботи нічим іншим не можемо визволитися, як молитвою і визнанням наших гріхів перед Богом. Бо як хто, сповіщаючи вірному своєму другові скорботу свою, отримує якусь розраду й втіху, так тим більше, коли Богові, Який милосердний за природою і близький до тих, що кличуть Його в істині, сповіщаємо скорботи серця нашого й гріхи наші визнаючи, упокорюємося, падаємо перед величчю Його, отримуємо або визволення, коли волі Його угодно і нам корисно, або неодмінно полегшення й втіху: «Поклич Мене в день скорботи твоєї, і Я визволю тебе» (Пс. 49:15). Слухай втішливе Боже слово: «За гріх Я трохи засмутив його, і вразив його, і відвернув Лице Моє від нього; і він засмутився, і пішов сумний шляхом своїм; і Я дороги його бачив, і зцілив його, і втішив його, і дав йому втіху істинну» (Іс. 57:17–18). Кожна скорбота і біда від гріха буває, і якби не було гріха, не було б і скорботи. Для того посилається скорбота, щоб гріх очистився, і коли очиститься гріх, який скорботу приносить, відніметься й сама скорбота. Тому слід покаянням, визнанням перед Богом, молитвою і вірою очищати гріхи, щоб так і скорбота, і смуток благодаттю Божою відпали, і прийшла втіха, як сонце після похмурих днів, або як їжа після посту, — приємна й весела."],"h":"6. Молитва в усякій скорботі й тіснині"}],"notes":[]},{"u":"Молитви сербських святих","e":"Prayers of the Serbian Saints","secs":[{"ps":["Господи, Господи, пощади й помилуй раба Твого, бо знаю, що беззаконня мої воістину великі й перед Тобою завжди не утаєні, Господи! Тому покладу початок у серці своєму: нехай воно тремтить і боїться імені Твого святого. За апостолом Павлом мовлю: ви, які маєте жінок, як і ті, хто їх не має, дотримуйтесь чистоти й заповідей Господніх. Тому і я Тобі даю, як заставу мого твердого заступництва, хоронительку Пречисту й нескверну Твою Матір. Нехай заради імені Твого святого й заради Тебе відокремлюся від зв’язку з дружиною моєю, і ставлю Тебе, Владико мій Ісусе Христе, проводирем і хоронителем старості моєї та наставником на шляху, ідучи яким і славлячи Твоє ім’я, не спіткнуся.","Ще й збудую храм Пречистій і Пренепорочній Матері Твоїй Добротворительці, і виконаю обітниці свої, які вимовили мої уста."],"h":"Молитва прп. Симеона Мироточивого"},{"ps":["Святі Христові заступники й архангели, пророки й апостоли, мученики й ієрархи, преподобні отці, пустельники й ви, монахи й преподобні жони, — виллєте всі молитви свої перед Владикою всіх, Господом нашим Ісусом Христом. Нехай мене не засудить у день страшного й грізного випробування, але нехай буде мені того дня й години милостивий, спокійний, втішний, і мені, заради молитов Пречистої Своєї Матері й ваших святих, нехай дасть перейти життєву бурю, досягти тихої й істинної й нехвилюваної пристані та бачити світло моє незаходиме, Господа і Спаса і Бога мого, царя Ісуса Христа, Який у святині хвала Ізраїлева. Бо пророк каже: «На Тебе надіялися наші отці і не посоромилися, на Тебе надіялися і спаслися».","Тому, о Господи, мене, бідного, що надіюся на милість Твою, не залиш, не відштовхни того, хто згрішив. Помилуй, Спасе, створіння Твоє, бо, відмовившись від краси цього світу, за Тобою побіжить, хвалячи й славлячи святе й незлобиве ім’я Твоє, Отця і Сина і Святого Духа, нині і повсякчас, і навіки віків."],"h":"Обітна молитва прп. Симеона Мироточивого"},{"ps":["Дякую Тобі, Владико Господи Боже мій, Ісусе Христе, милостивий Господи й Чоловіколюбче, що мене вдостоїв сьогодні бачити початок шляху Твого спасіння, адже ті, хто приходять до істинного розуму, живуть без блукання.","Тому, душе моя, віддайся й поспішай до покаяння, бо Владика Твій кличе. Бо цим псалмом тобі приклад показав, кажучи: «З уст дітей і немовлят приготував Собі хвалу», тому не лінуйся! Хіба не бачиш молодих, які шукають потрібного собі і які йдуть поперед тебе? Не озирайся, так само як і жінка Лота, не дивися на красу цього світу, що швидко зникає, щоб не сталося з тобою за притчею про багача, але довірся Господу й пам’ятай свої обіцянки. Бо час наближається, бо сокира при корені дерев лежить, і розмежовуються поля; розумій, час жнива!","Жених перед дверима, а ти не готова. Остерігайся, щоб не залишитися з того боку, стукаючи. Бо слухай, що Христос каже: «Прийдіть до Мене всі струджені й обтяжені, і Я заспокою вас», як і інше. Тож встань, встань і трудися під благим ярмом Христовим і легким тягарем Його, щоб відчинив тобі Христос двері царства Свого."],"h":"Молитва прп. Симеона Мироточивого напередодні чернечого постригу"},{"ps":["Господи Ісусе Христе, Спасителю наш, настановнику заблуклих, Отче істинного світла, єдинородне Слове Отче, проводирю старих, утвердження молодих, приведи мою немовлячу слабкість до волі істинного Твого розуміння, щоб, випередивши, я висунувся на цьому шляху, на якому і пан мій, цей мій охоронець, поспішає йти.","Бо Ти знаєш, Серцевидче, Господи Ісусе Христе, що весь цей світ не полюбить душа моя, ні те, що в ньому.","Тому, о Господи, не погуби з безбожниками душу мою, ні з володарями віку цього, але, змилувавшись наді мною, недостойним, поспіши, щоб виконати на мені євангельське слово, яке вимовили пречисті й нелживі уста Твої: «Кожен, хто залишить батька свого й матір, царські доми й владу заради імені Мого, отримає во сто крат і успадкує життя вічне».","І тому в руки Твої віддаю Тобі дух мій, і без зволікання припавши до Тебе, іду за Тобою, Творче мій!"],"h":"Молитва святителя Сави Сербського"}],"notes":[]}];
export default D;
